window.CNXH_SOLVED_EXAMS=[{"code":"131120I","number":1,"question":"Trong cơ cấu xã hội, loại hình cơ cấu nào là cơ bản và có vị trí quyết định, chi phối các loại hình cơ cấu xã hội khác?","options":{"A":"Cơ cấu xã hội - nghề nghiệp","B":"Cơ cấu xã hội - dân cư","C":"Cơ cấu xã hội - giai cấp","D":"Cơ cấu xã hội - dân tộc"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Cơ cấu xã hội - giai cấp gắn với sở hữu tư liệu sản xuất, tổ chức quản lý và địa vị chính trị - xã hội nên được xác định là loại cơ cấu cơ bản và có ảnh hưởng lớn đến các cơ cấu khác."},{"code":"131120I","number":2,"question":"Yếu tố nào sau đây là cơ sở để liên kết các bộ phận, các thành viên của dân tộc, tạo nên nền tảng cho sự vững chắc của cộng đồng dân tộc?","options":{"A":"Có chung văn hóa, tâm lý, lãnh thổ","B":"Có chung sinh hoạt về kinh tế","C":"Có chung ngôn ngữ","D":"Có chung lãnh thổ"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Sinh hoạt kinh tế chung tạo sự liên hệ vật chất thường xuyên giữa các bộ phận dân tộc, qua đó góp phần củng cố sự thống nhất cộng đồng."},{"code":"131120I","number":3,"question":"Điền vào chỗ trống: “Tất cả các giai cấp khác đều suy tàn và tiêu vong cùng với sự phát triển của đại công nghiệp, còn giai cấp vô sản lại là [.........] của bản thân nền đại công nghiệp”","options":{"A":"Lực lượng","B":"Chủ thể","C":"Sự phát triển","D":"Sản phẩm"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Câu trích dẫn nói giai cấp vô sản là sản phẩm của đại công nghiệp, không phải chủ thể hay lực lượng theo cách điền từ này."},{"code":"131120I","number":4,"question":"Theo quan điểm của Mác và Ăngghen, nguồn gốc ra đời của Nhà nước là:","options":{"A":"Thượng đế sáng tạo ra Nhà nước để cai trị con người","B":"Giải quyết mâu thuẫn giai cấp không thể điều hoà được","C":"Tham vọng thống trị thế giới của con người","D":"Mong muôn xoá bỏ xã hội cũ, xây dựng xã hội mới"},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Trong cách tiếp cận Mác-xít, Nhà nước xuất hiện gắn với các đối kháng giai cấp không thể điều hòa."},{"code":"131120I","number":5,"question":"Hiểu vấn đề “bỏ qua” chế độ tư bản chủ nghĩa ở nước ta như thế nào là đúng:","options":{"A":"Là sự “phát triển rút ngắn” và “bỏ qua” việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa","B":"Là “bỏ qua” sự phát triển của lực lượng sản xuất","C":"Là sự phát triển tuần tự","D":"Các phương án trên đều đúng"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Bỏ qua chế độ tư bản chủ nghĩa là không xác lập địa vị thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa; không có nghĩa là bỏ qua phát triển lực lượng sản xuất."},{"code":"131120I","number":6,"question":"Tại sao khi giải quyết vấn đề tôn giáo phải có quan điểm lịch sử?","options":{"A":"Vì mỗi thời kỳ lịch sử khác nhau, vai trò, tác động của từng tôn giáo đối với đời sống xã hội không giống nhau","B":"Vì tôn giáo ra đời, tồn tại và biến đổi trong một giai đoạn lịch sử nhất định","C":"Vì mỗi tôn giáo có triết lý riêng của mình","D":"Cả A, B đều đúng"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Đáp án D đúng vì vai trò, hình thức và tác động của tôn giáo thay đổi theo từng thời kỳ lịch sử và hoàn cảnh xã hội cụ thể; do đó khi giải quyết vấn đề tôn giáo phải xét cả điều kiện lịch sử và bối cảnh thực tế."},{"code":"131120I","number":7,"question":"Điều kiện khách quan quy định sứ mệnh lịch sử của giai cấp công nhân là:","options":{"A":"Địa vị kinh tế - xã hội và địa vị chính trị - xã hội","B":"Đảng Cộng sản lãnh đạo","C":"Bản thân giai cấp công nhân phát triển về số lượng và chất lượng","D":"Cả A và B"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Điều kiện khách quan xuất phát từ địa vị kinh tế - xã hội và chính trị - xã hội; sự phát triển của công nhân và vai trò lãnh đạo của Đảng thuộc nhân tố chủ quan."},{"code":"131120I","number":8,"question":"Lênin chia hình thái kinh tế - xã hội cộng sản chủ nghĩa thành mấy giai đoạn?","options":{"A":"Hai giai đoạn: chủ nghĩa xã hội và chủ nghĩa cộng sản","B":"Ba giai đoạn: Thời kì quá độ lên chủ nghĩa xã hội, chủ nghĩa xã hội và chủ nghĩa cộng sản","C":"Bốn giai đoạn: Thời kì quá độ lên CNXH, CNXH, chủ nghĩa xã hội phát triển cao và cộng sản chủ nghĩa","D":"Tất cả các câu đều sai"},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Lênin trình bày ba thời kỳ: thời kỳ quá độ, giai đoạn thấp (CNXH), giai đoạn cao (CNCS)."},{"code":"131120I","number":9,"question":"Đặc điểm cơ bản nhất của nước ta khi bước vào thời kỳ quá độ lên chủ nghĩa xã hội là gì?","options":{"A":"Tồn tại nhiều phong tục, tập quán lạc hậu","B":"Từ một nền sản xuất nhỏ là phổ biến quá độ lên chủ nghĩa xã hội không qua chế độ tư bản chủ nghĩa","C":"Nhân dân có truyền thống lao động cần cù, sáng tạo","D":"Các thế lực thù địch thường xuyên chống phá công cuộc xây dựng chủ nghĩa xã hội của nhân dân ta"},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Đặc điểm xuất phát của Việt Nam là từ nền sản xuất nhỏ phổ biến, đi lên CNXH không qua chế độ TBCN."},{"code":"131120I","number":10,"question":"Chức năng nào của gia đình đảm bảo tái sản xuất nguồn lao động và sức lao động cho xã hội?","options":{"A":"Chức năng nuôi dưỡng, giáo dục","B":"Chức năng kinh tế","C":"Chức năng tái sản xuất ra con người","D":"Chức năng thỏa mãn các nhu cầu tâm sinh lý, duy trì tình cảm"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chức năng tái sản xuất ra con người duy trì các thế hệ và cung cấp nguồn nhân lực tương lai cho xã hội; nuôi dưỡng và giáo dục là chức năng khác của gia đình."},{"code":"131120I","number":11,"question":"Tiền đề kinh tế cho sự hình thành tư tưởng xã hội chủ nghĩa là:","options":{"A":"Sự xuất hiện giai cấp thống trị","B":"Sự xuất hiện nhà nước","C":"Sự xuất hiện chế độ tư hữu","D":"Cả A, B, C đều đúng"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chế độ tư hữu làm nảy sinh phân hóa sở hữu, giai cấp và bóc lột; đó là tiền đề kinh tế khiến tư tưởng hướng tới một xã hội công bằng hơn xuất hiện."},{"code":"131120I","number":12,"question":"Nội dung nào quan trọng nhất trong xây dựng khối liên minh giữa giai cấp công nhân với giai cấp nông dân và tầng lớp khác?","options":{"A":"Liên minh về chính trị","B":"Liên minh về xã hội","C":"Liên minh về kinh tế","D":"Liên minh về văn hóa"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Liên minh kinh tế tạo cơ sở lợi ích vật chất chung, hỗ trợ gắn kết công nhân, nông dân và các tầng lớp trong thời kỳ quá độ."},{"code":"131120I","number":13,"question":"Trong CNTB, mâu thuẫn về mặt kinh tế đã biểu hiện ra thành mâu thuẫn chính trị giữa:","options":{"A":"Giai cấp tư sản với giai cấp công nhân","B":"Giai cấp tư sản với giai cấp tiểu tư sản","C":"Giai cấp tư sản với giai cấp nông dân","D":"Giai cấp tư sản với giai cấp địa chủ"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong chủ nghĩa tư bản, quan hệ sở hữu tư liệu sản xuất và lợi ích kinh tế đối lập giữa tư sản và công nhân là cơ sở của mâu thuẫn chính trị giữa hai giai cấp."},{"code":"131120I","number":14,"question":"Với dự báo khoa học của chủ nghĩa Mác - Lênin, khi đến một giai đoạn mà xã hội không còn giai cấp, không còn đấu tranh giai cấp thì:","options":{"A":"Nhà nước còn tồn tại","B":"Nhà nước tự tiêu vong","C":"Nhà nước phồn thịnh","D":"Nhà nước phát triển"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo dự báo của chủ nghĩa Mác - Lênin, khi xã hội không còn giai cấp và đối kháng giai cấp thì nhà nước mất cơ sở tồn tại và dần tự tiêu vong."},{"code":"131120I","number":15,"question":"Trong cách mạng xã hội chủ nghĩa, ai được xác định là “người bạn đồng minh tự nhiên” của giai cấp công nhân?","options":{"A":"Doanh nhân","B":"Tư sản","C":"Nông dân","D":"Trí thức"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Giai cấp nông dân được xác định là “người bạn đồng minh tự nhiên” của giai cấp công nhân vì có nhiều lợi ích cơ bản gần gũi trong đấu tranh và xây dựng xã hội mới."},{"code":"131120I","number":16,"question":"Điền vào chỗ trống: “[.........] là hệ thống các giai cấp, tầng lớp xã hội tồn tại khách quan và mối quan hệ giữa chúng về sở hữu, về quản lý, về địa vị chính trị - xã hội trong một hệ thống sản xuất nhất định”","options":{"A":"Cơ cấu xã hội - giới tính","B":"Cơ cấu xã hội - giai cấp","C":"Cơ cấu xã hội - nghề nghiệp","D":"Cơ cấu xã hội – địa lý"},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Câu mô tả chính xác cơ cấu xã hội – giai cấp và mối quan hệ về sở hữu, quản lý, địa vị."},{"code":"131120I","number":17,"question":"Lịch sử loài người đã từng xuất hiện các chế độ dân chủ:","options":{"A":"Chủ nô, phong kiến, tư sản, vô sản","B":"Chủ nô, phong kiến, tư sản.","C":"Công xã nguyên thủy, chủ nô, phong kiến, tư sản, vô sản","D":"Chủ nô, tư sản, vô sản"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Theo cách phân loại trong tài liệu môn học, ba nền dân chủ gắn với nhà nước là chủ nô, tư sản và vô sản."},{"code":"131120I","number":18,"question":"Phân phối theo lao động là hình thức phân phối cơ bản của xã hội nào?","options":{"A":"Xã hội xã hội chủ nghĩa","B":"Xã hội cộng sản chủ nghĩa","C":"Xã hội tư bản chủ nghĩa","D":"Các phương án trên đều sai"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Phân phối theo lao động là hình thức phân phối cơ bản của chủ nghĩa xã hội; giai đoạn cộng sản chủ nghĩa cao hướng tới phân phối theo nhu cầu."},{"code":"131120I","number":19,"question":"Trong thời kỳ quá độ lên chủ nghĩa xã hội, cơ cấu xã hội – giai cấp bị quy định bởi:","options":{"A":"Cơ cấu kinh tế","B":"Cơ cấu văn hóa xã hội","C":"Cơ cấu nhân sự","D":"Cơ cấu chính trị"},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Cơ cấu kinh tế là nền tảng chi phối tính chất và sự vận động của cơ cấu xã hội – giai cấp."},{"code":"131120I","number":20,"question":"Theo nghĩa hẹp, “dân tộc” được hiểu là:","options":{"A":"Tộc người","B":"Quốc gia","C":"Bộ lạc","D":"Bộ tộc"},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Dân tộc theo nghĩa hẹp chỉ tộc người; theo nghĩa rộng chỉ cộng đồng quốc gia – dân tộc."},{"code":"131120I","number":21,"question":"Quan hệ nào nảy sinh từ quan hệ hôn nhân và là mối quan hệ tự nhiên, là yếu tố mạnh mẽ nhất gắn kết các thành viên trong gia đình với nhau?","options":{"A":"Hôn nhân","B":"Huyết thống","C":"Nuôi dưỡng","D":"Cả B và C"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Quan hệ huyết thống nảy sinh từ quan hệ hôn nhân, là quan hệ tự nhiên giữa các thế hệ và tạo sự gắn kết mạnh mẽ giữa các thành viên; do đó B đúng."},{"code":"131120I","number":22,"question":"Tư tưởng xã hội chủ nghĩa bắt đầu hình thành ở chế độ xã hội nào?","options":{"A":"Chế độ tư bản chủ nghĩa","B":"Chế độ chiếm hữu nô lệ","C":"Chế độ công xã nguyên thủy","D":"Chế độ phong kiến"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Các tư tưởng hướng tới công bằng xã hội xuất hiện từ khi xã hội bắt đầu phân hóa giai cấp, có chiếm hữu nô lệ và đối kháng giữa người bóc lột với người bị bóc lột."},{"code":"131120I","number":23,"question":"“Sự xuất hiện của hình thái kinh tế - xã hội CSCN ở các nước tư bản có trình độ phát triển trung bình và những nước thuộc địa sau khi được giải phóng” là quan điểm của ai?","options":{"A":"Ph.Ăngghen","B":"C.Mác","C":"V.I.Lênin","D":"Hồ Chí Minh"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Lenin phát triển lý luận về khả năng quá độ lên chủ nghĩa xã hội ở những nước tư bản phát triển trung bình và các nước thuộc địa sau giải phóng, nên C đúng."},{"code":"131120I","number":24,"question":"Tác phẩm nào được V.I.Lênin đánh giá là “tác phẩm chủ yếu và cơ bản trình bày chủ nghĩa xã hội khoa học”?","options":{"A":"Tư bản","B":"Tuyên ngôn Đảng cộng sản","C":"Ba nguồn gốc và ba bộ phận hợp thành chủ nghĩa Mác","D":"Nguồn gốc gia đình, chế độ tư hữu và Nhà nước"},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Lênin nhắc đến bộ Tư bản của Mác khi nêu tác phẩm chủ yếu trình bày CNXHKH, không phải Tuyên ngôn."},{"code":"131120I","number":25,"question":"Phát kiến nào của C. Mác và Ăngghen đã khẳng định về mặt kinh tế sự diệt vong không tránh khỏi của chủ nghĩa tư bản và sự ra đời tất yếu của chủ nghĩa xã hội?","options":{"A":"Học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân","B":"Học thuyết về giá trị thặng dư","C":"Chủ nghĩa duy vật lịch sử","D":"Tính hai mặt của lao động sản xuất hàng hóa"},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Học thuyết giá trị thặng dư làm rõ cơ chế kinh tế của chủ nghĩa tư bản và cơ sở lịch sử của sự thay thế."},{"code":"131120I","number":26,"question":"“Giai cấp vô sản không thể hoàn thành sứ mệnh lịch sử nếu không tổ chức ra chính đảng của giai cấp mình” – là luận điểm được trình bày trong tác phẩm nào?","options":{"A":"Tuyên ngôn Đảng cộng sản","B":"Tình cảnh giai cấp công nhân Anh","C":"Những nguyên tắc của Chủ nghĩa cộng sản","D":"Đấu tranh giai cấp ở Pháp 1848-1850"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tuyên ngôn của Đảng Cộng sản khẳng định giai cấp vô sản phải tổ chức thành một chính đảng độc lập để thực hiện thắng lợi sứ mệnh lịch sử; vì vậy A."},{"code":"131120I","number":27,"question":"Theo V.I.Lênin, hệ thống chuyên chính vô sản ở nước Nga bao gồm:","options":{"A":"Đảng Bônsêvic lãnh đạo và liên minh công nhân – nông dân – trí thức","B":"Chính quyền Xô viết + trật tự ở đường sắt Phổ + kỹ thuật và cách thức tổ chức các tơ rớt ở Mỹ + ngành giáo dục quốc dân Mỹ","C":"Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và quốc tế cộng sản","D":"Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và tổ chức công đoàn"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong các phương án, A mô tả đúng cấu trúc cơ bản của hệ thống chuyên chính vô sản ở Nga: Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và các tổ chức quần chúng như công đoàn tham gia; B là công thức về tổ chức xây dựng kinh tế, không phải hệ thống chuyên chính."},{"code":"131120I","number":28,"question":"Theo V.I.Lênin, để dần dần cải tiến chế độ sở hữu của các nhà tư bản hạng trung và hạng nhỏ thành sở hữu công cộng, cần phải sử dụng rộng rãi hình thức kinh tế nào?","options":{"A":"Tư bản thân hữu","B":"Tư bản tư nhân","C":"Tư bản nhà nước","D":"Tư bản cho vay"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Lenin chủ trương sử dụng rộng rãi chủ nghĩa tư bản nhà nước như một hình thức quá độ để từng bước cải biến sở hữu tư nhân vừa và nhỏ theo hướng xã hội chủ nghĩa, nên D."},{"code":"131120I","number":29,"question":"“Dựa trên cơ sở những tư liệu thực tiễn của lịch sử để rút ra những nhận định, những khái quát về lý luận có kết cấu chặt chẽ, khoa học” là nội dung của phương pháp nghiên cứu nào trong môn CNXHKH?","options":{"A":"Phương pháp so sánh","B":"Phương pháp khảo sát và phân tích về mặt chính trị - xã hội","C":"Phương pháp kết hợp lịch sử và logic","D":"Phương pháp điều tra xã hội học"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Phương pháp kết hợp lịch sử và logic xuất phát từ tư liệu lịch sử cụ thể rồi khái quát thành những kết luận lý luận có cấu trúc và tính quy luật; vì vậy D đúng."},{"code":"131120I","number":30,"question":"Nhân tố quan trọng hàng đầu bảo đảm thắng lợi của sự nghiệp đổi mới, hội nhập và phát triển ở nước ta là:","options":{"A":"Giữ vững và tăng cường vai trò lãnh đạo của Đảng cộng sản Việt Nam","B":"Đảm bảo liên minh công – nông – trí thức","C":"Phát huy vai trò làm chủ của nhân dân","D":"Xây dựng Nhà nước pháp quyền XHCN"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách trình bày của môn học, giữ vững và tăng cường vai trò lãnh đạo của Đảng Cộng sản Việt Nam là nhân tố quan trọng hàng đầu bảo đảm thắng lợi của đổi mới, hội nhập và phát triển."},{"code":"131120I","number":31,"question":"Căn cứ vào tính chất quyền lực, Nhà nước có những chức năng nào?","options":{"A":"Chức năng kinh tế, chính trị, văn hoá, xã hội","B":"Chức năng đối nội và đối ngoại","C":"Chức năng giai cấp và chức năng xã hội","D":"Cả A, B, C đều đúng"},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Xét theo tính chất thực hiện quyền lực có chức năng giai cấp và chức năng xã hội, không phải liệt kê theo lĩnh vực hoạt động."},{"code":"131120I","number":32,"question":"Yếu tố quyết định giai cấp nông dân không thể đảm nhận sứ mệnh lịch sử thực hiện việc chuyển biến từ xã hội TBCN lên XHCN","options":{"A":"Họ không có hệ tư tưởng riêng độc lập","B":"Họ mang tính tư hữu cao","C":"Họ không đại diện cho phương thức sản xuất tiến bộ","D":"Họ không có chính Đảng riêng độc lập"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Nông dân không đại diện cho phương thức sản xuất tiên tiến và hiện đại nên theo lý luận của môn học không thể giữ vai trò lãnh đạo quá trình chuyển từ chủ nghĩa tư bản lên chủ nghĩa xã hội; C là nguyên nhân quyết định."},{"code":"131120I","number":33,"question":"Hình thức dân chủ quân sự xuất hiện trong xã hội nào?","options":{"A":"Công xã nguyên thuỷ","B":"Chiếm hữu nô lệ","C":"Phong kiến","D":"Tư bản chủ nghĩa"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Dân chủ quân sự là hình thức dân chủ sơ khai xuất hiện ở giai đoạn cuối của xã hội công xã nguyên thủy, trước khi nhà nước và nền dân chủ chủ nô hình thành; vì vậy D."},{"code":"131120I","number":34,"question":"Nội dung cốt lõi trong chính sách tôn giáo của Đảng và Nhà nước ta là gì?","options":{"A":"Nâng cao trách nhiệm của cả hệ thống chính trị","B":"Vấn đề theo đạo và truyền đạo","C":"Tăng cường đại đoàn kết dân tộc","D":"Công tác vận động quần chúng"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tài liệu Chương 6 xác định nội dung cốt lõi của công tác/chính sách tôn giáo là công tác vận động quần chúng, nên D đúng."},{"code":"131120I","number":35,"question":"Biện pháp nào là không đúng để phát triển kinh tế trong thời kỳ quá độ lên CNXH bỏ qua chế độ tư bản chủ nghĩa?","options":{"A":"Thực hiện nhất quán lâu dài nền kinh tế nhiều thành phần trong đó kinh tế nhà nước là chủ đạo.","B":"Phát triển nền sản xuất hàng hoá theo cơ chế thị trường.","C":"Dựa trên một hình thức phân phối là phân phối theo lao động.","D":"Thông qua chế độ hợp tác tự nguyện dẫn dắt nông dân đi lên CNXH."},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Trong thời kỳ quá độ tồn tại nhiều hình thức phân phối; không chỉ duy nhất phân phối theo lao động."},{"code":"131120I","number":36,"question":"Như thế nào là chế độ hôn nhân tiến bộ?","options":{"A":"Hôn nhân tự nguyện","B":"Một vợ một chồng, bình đẳng","C":"Được đảm bảo về pháp lý","D":"Cả A, B và C."},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Hôn nhân tiến bộ gồm ba yêu cầu gắn bó: tự nguyện; một vợ một chồng và vợ chồng bình đẳng; kết hôn, ly hôn được pháp luật bảo đảm. Vì A, B, C đều đúng nên chọn D."},{"code":"131120I","number":37,"question":"Ở nước ta, tổ chức nào hoạt động theo phương thức hiệp thương dân chủ, phối hợp và thống nhất hành động giữa các thành viên theo chương trình hoạt động chung:","options":{"A":"Đảng Cộng sản Việt Nam","B":"Chính phủ","C":"Quốc hội","D":"Mặt trận Tổ quốc Việt Nam"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Mặt trận Tổ quốc Việt Nam hoạt động theo phương thức hiệp thương dân chủ, phối hợp và thống nhất hành động giữa các thành viên."},{"code":"131120I","number":38,"question":"Theo quan điểm của chủ nghĩa Mác Lênin, xét về phương diện tổ chức quản lý xã hội thì dân chủ được hiểu là:","options":{"A":"Chế độ dân chủ","B":"Hình thái nhà nước","C":"Nguyên tắc tập trung dân chủ","D":"Quyền lực thuộc về nhân dân"},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Xét từ phương diện tổ chức và quản lý xã hội, dân chủ được xem là một hình thức/hình thái nhà nước."},{"code":"131120I","number":39,"question":"Đảng Cộng sản Việt Nam ra đời là sự kết hợp của:","options":{"A":"Chủ nghĩa Mác – Lênin, phong trào công nhân và phong trào yêu nước","B":"Chủ nghĩa Mác – Lênin, phong trào công nhân","C":"Chủ nghĩa Mác – Lênin, phong trào công nhân và tư tưởng Hồ Chí Minh","D":"Chủ nghĩa Mác – Lênin, phong trào công nhân và phong trào chống thực dân"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Ở Việt Nam, Đảng Cộng sản ra đời từ sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước; đây là nét đặc thù so với công thức chung."},{"code":"131120I","number":40,"question":"Theo quy định của giai cấp cầm quyền trong nền dân chủ chủ nô, “nhân dân” là:","options":{"A":"Chủ nô, tăng lữ, thương gia và một số trí thức","B":"Giai cấp chủ nô và nô lệ","C":"Thương gia và nô lệ","D":"Tăng lữ và một số trí thức"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong nền dân chủ chủ nô, khái niệm “nhân dân” theo quy định của giai cấp cầm quyền chỉ bao gồm những người tự do như chủ nô, tăng lữ, thương gia và một số trí thức, không bao gồm nô lệ; A phù hợp nhất."},{"code":"131120II","number":1,"question":"Nhà nước là:","options":{"A":"Tổ chức chính trị của giai cấp thống trị về kinh tế nhằm bảo vệ trật tự hiện hành và đàn áp sự phản kháng của các giai cấp khác.","B":"Tổ chức chính trị của giai cấp thống trị về kinh tế nhằm bảo vệ trật tự hiện hành và bảo vệ lợi ích của tất cả các giai cấp khác","C":"Tổ chức chính trị đứng trên các giai cấp nhằm bảo vệ tất cả các giai cấp.","D":"Tổ chức chính trị đứng ngoài xã hội, cai trị xã hội"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo lý luận Mác - Lênin, nhà nước là tổ chức quyền lực chính trị của giai cấp thống trị về kinh tế, dùng để duy trì trật tự hiện hành và trấn áp sự phản kháng của các giai cấp đối lập; A phù hợp nhất."},{"code":"131120II","number":2,"question":"Trong cách mạng xã hội chủ nghĩa, ai được xác định là “người bạn đồng minh tự nhiên” của giai cấp công nhân?","options":{"A":"Doanh nhân","B":"Tư sản","C":"Trí thức","D":"Nông dân"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Giai cấp nông dân được xác định là “người bạn đồng minh tự nhiên” của giai cấp công nhân vì có nhiều lợi ích cơ bản gần gũi trong đấu tranh và xây dựng xã hội mới."},{"code":"131120II","number":3,"question":"Điền vào chỗ trống cho đoạn văn sau đây: “ [.........] là sản phẩm của sự kết hợp chủ nghĩa Mác – Lênin với phong trào công nhân trong cuộc đấu tranh thực hiện sứ mệnh lịch sử của giai cấp công nhân”","options":{"A":"Giai cấp công nhân","B":"Đảng Cộng sản","C":"Đảng chính trị","D":"Giai cấp tư sản"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Đảng Cộng sản là sản phẩm của sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân; đây là công thức chung về sự ra đời của chính đảng giai cấp công nhân."},{"code":"131120II","number":4,"question":"Trong thời kỳ quá độ lên chủ nghĩa xã hội, cơ cấu xã hội – giai cấp bị quy định bởi:","options":{"A":"Cơ cấu văn hóa xã hội","B":"Cơ cấu chính trị","C":"Cơ cấu nhân sự","D":"Cơ cấu kinh tế"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Trong thời kỳ quá độ, sự biến đổi cơ cấu xã hội – giai cấp chịu sự quy định của cơ cấu kinh tế."},{"code":"131120II","number":5,"question":"Điền vào chỗ trống: “tất cả mọi tôn giáo chẳng qua chỉ là sự phản ánh [.........] vào trong đầu óc của con người – của những lực lượng ở bên ngoài chi phối cuộc sống hàng ngày của họ”","options":{"A":"Niềm tin","B":"Hư ảo","C":"Sinh động","D":"Hiện thực"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Cụm từ kinh điển là “sự phản ánh hư ảo” các lực lượng bên ngoài chi phối đời sống con người, nên từ cần điền là “hư ảo”."},{"code":"131120II","number":6,"question":"Theo Mác và Ph.Ăngghen, có hai tiêu chí cơ bản xác định giai cấp công nhân đó là:","options":{"A":"Về phương thức lao động, phương thức sản xuất và vị trí của giai cấp công nhân trong quan hệ sản xuất xã hội chủ nghĩa","B":"Về phương thức lao động, phương thức sản xuất và vị trí của giai cấp công nhân trong quan hệ sản xuất.","C":"Về phương thức lao động, phương thức sản xuất và vị trí của giai cấp công nhân trong quan hệ sản xuất xã hội","D":"Về phương thức lao động, phương thức sản xuất và vị trí của giai cấp công nhân trong quan hệ sản xuất tư bản chủ nghĩa"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Hai thuộc tính cơ bản gắn với phương thức lao động công nghiệp và vị trí trong quan hệ sản xuất tư bản chủ nghĩa."},{"code":"131120II","number":7,"question":"Hạn chế cơ bản của các nhà tư tưởng xã hội chủ nghĩa không tưởng là:","options":{"A":"Không chủ trương xóa bỏ chế độ áp bức bóc lột","B":"Không thể phát hiện ra lực lượng xã hội tiên phong thực hiện cuộc chuyển biến cách mạng xã hội","C":"Mong muốn thực hiện chế độ bình quân trong phân phối","D":"Không chủ trương xóa bỏ chế độ tư hữu về tư liệu sản xuất"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Hạn chế cơ bản của chủ nghĩa xã hội không tưởng là chưa phát hiện được lực lượng xã hội tiên phong có khả năng hiện thực hóa cuộc chuyển biến cách mạng, tức vai trò của giai cấp công nhân."},{"code":"131120II","number":8,"question":"Tiền đề kinh tế cho sự hình thành tư tưởng xã hội chủ nghĩa là:","options":{"A":"Sự xuất hiện giai cấp thống trị","B":"Sự xuất hiện nhà nước","C":"Sự xuất hiện chế độ tư hữu","D":"Cả A, B và C đều đúng"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chế độ tư hữu làm nảy sinh phân hóa sở hữu, giai cấp và bóc lột; đó là tiền đề kinh tế khiến tư tưởng hướng tới một xã hội công bằng hơn xuất hiện."},{"code":"131120II","number":9,"question":"Chủ nghĩa xã hội khoa học ra đời từ điều kiện kinh tế - xã hội nào?","options":{"A":"Sự ra đời của giai cấp công nhân","B":"Phương thức sản xuất tư bản chủ nghĩa gắn liền với công trường thủ công","C":"Phương thức sản xuất tư bản chủ nghĩa phát triển mạnh mẽ gắn liền với nền đại công nghiệp","D":"Sự ra đời của Đảng cộng sản"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chủ nghĩa xã hội khoa học ra đời khi phương thức sản xuất tư bản chủ nghĩa phát triển mạnh trên nền đại công nghiệp, làm mâu thuẫn xã hội và phong trào công nhân phát triển."},{"code":"131120II","number":10,"question":"Điều kiện chủ quan quyết định sự thành công khi thực hiện sứ mệnh lịch sử của giai cấp công nhân là:","options":{"A":"Bản thân giai cấp công nhân phát triển về số lượng và chất lượng","B":"Đảng Cộng sản lãnh đạo","C":"Địa vị kinh tế - xã hội và địa vị chính trị - xã hội quy định","D":"Cả A, B"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Điều kiện chủ quan gồm sự phát triển của bản thân giai cấp công nhân và sự lãnh đạo của Đảng Cộng sản."},{"code":"131120II","number":11,"question":"Tôn giáo ra đời là do?","options":{"A":"Sự yếu kém của trình độ lực lượng sản xuất","B":"Sự sợ hãi trước sức mạnh của tự nhiên và xã hội","C":"Sự bần cùng của kinh tế, áp bức về chính trị","D":"Cả A, B và C đều đúng"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Các nguồn gốc nhận thức, tự nhiên và xã hội – kinh tế đều góp phần giải thích sự ra đời, tồn tại tôn giáo theo giáo trình."},{"code":"131120II","number":12,"question":"Phong trào đấu tranh của giai cấp công nhân Lion (Pháp) đã chuyển từ khẩu hiệu “Sống có việc làm hay là chết trong đấu tranh” (1931) sang “Cộng hòa hay là chết” (1934) thể hiện cho sự phát triển:","options":{"A":"Từ mục đích đấu tranh chính trị sang đấu tranh văn hóa, tư tưởng","B":"Từ mục đích đấu tranh văn hóa, tư tưởng sang mục đích xóa bỏ bóc lột","C":"Từ mục đích đấu tranh kinh tế sang đấu tranh chính trị","D":"Từ mục đích đấu tranh kinh tế sang mục đích đấu tranh văn hóa, tư tưởng"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Khẩu hiệu từ đòi “việc làm” sang đòi “cộng hòa” cho thấy phong trào chuyển từ yêu sách kinh tế sang mục tiêu chính trị, nên C đúng."},{"code":"131120II","number":13,"question":"Phát kiến nào của C. Mác và Ăngghen là sự khẳng định về mặt triết học sự sụp đổ của chủ nghĩa tư bản và sự thắng lợi của chủ nghĩa xã hội đều tất yếu như nhau?","options":{"A":"Tính hai mặt của lao động sản xuất hàng hóa","B":"Học thuyết về giá trị thặng dư","C":"Học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân","D":"Chủ nghĩa duy vật lịch sử"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chủ nghĩa duy vật lịch sử giải thích về mặt triết học quy luật vận động và thay thế các hình thái kinh tế - xã hội; giá trị thặng dư là cơ sở kinh tế, còn sứ mệnh lịch sử xác định lực lượng thực hiện."},{"code":"131120II","number":14,"question":"CNXHKH phát triển trong khoảng thời gian từ sau 1895 đến năm 1917 thuộc giai đoạn nào sau đây trong lịch sử hình thành và phát triển của CNXHKH","options":{"A":"Giai đoạn Mác và Ăngghen","B":"Giai đoạn từ sau Lênin mất","C":"Cả A,B,C đều sai","D":"Giai đoạn Lênin phát triển CNXHKH"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Mốc 1895–1917 nằm trong giai đoạn Lênin vận dụng và phát triển CNXHKH."},{"code":"131120II","number":15,"question":"Bản chất của chuyên chính vô sản là:","options":{"A":"Liên kết giai cấp vô sản các dân tộc trên thế giới","B":"Trấn áp bằng bạo lực đối với giai cấp bóc lột","C":"Giai cấp công nhân đưa ra được và thực hiện được kiểu tổ chức lao động xã hội cao hơn so với chủ nghĩa tư bản","D":"Học tập chủ nghĩa tư bản về khoa học kỹ thuật, kinh nghiệm quản lý kinh tế"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Bản chất của chuyên chính vô sản không chỉ là trấn áp; điểm sâu hơn là giai cấp công nhân tổ chức được kiểu lao động xã hội cao hơn chủ nghĩa tư bản và dùng quyền lực để xây dựng xã hội mới, nên C."},{"code":"131120II","number":16,"question":"Ba trụ cột cho sự phát triển nhanh và bền vững của Việt Nam là:","options":{"A":"Phát triển kinh tế là nhiệm vụ trung tâm, xây dựng Đảng là khâu then chốt và phát triển văn hóa là nền tảng tinh thần của xã hội","B":"Phát triển kinh tế là nhiệm vụ then chốt, xây dựng Đảng là khâu trung tâm và phát triển văn hóa là nền tảng tinh thần của xã hội","C":"Phát triển kinh tế là nhiệm vụ nền tảng, xây dựng Đảng là khâu then chốt và phát triển văn hóa là trung tâm tinh thần của xã hội","D":"Phát triển kinh tế là nhiệm vụ then chốt, xây dựng Đảng là khâu trung tâm và phát triển văn hóa là nền tảng then chốt của xã hội"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách hỏi “ba trụ cột” của đề, A đúng: kinh tế là trung tâm, xây dựng Đảng là then chốt, văn hóa là nền tảng tinh thần. Lưu ý slide Chương 3 hiện tại còn bổ sung quốc phòng - an ninh thành trụ cột trọng yếu, thường xuyên."},{"code":"131120II","number":17,"question":"“Dựa trên cơ sở những tư liệu thực tiễn của lịch sử để rút ra những nhận định, những khái quát về lý luận có kết cấu chặt chẽ, khoa học” là nội dung của phương pháp nghiên cứu nào trong môn CNXHKH?","options":{"A":"Phương pháp điều tra xã hội học","B":"Phương pháp khảo sát và phân tích về mặt chính trị - xã hội","C":"Phương pháp so sánh","D":"Phương pháp kết hợp lịch sử và logic"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Phương pháp kết hợp lịch sử và logic xuất phát từ tư liệu lịch sử cụ thể rồi khái quát thành những kết luận lý luận có cấu trúc và tính quy luật; vì vậy D đúng."},{"code":"131120II","number":18,"question":"Phân phối theo lao động là hình thức phân phối cơ bản của xã hội nào?","options":{"A":"Xã hội xã hội chủ nghĩa","B":"Xã hội cộng sản chủ nghĩa","C":"Xã hội tư bản chủ nghĩa","D":"Các phương án trên đều sai"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Phân phối theo lao động là hình thức phân phối cơ bản của chủ nghĩa xã hội; giai đoạn cộng sản chủ nghĩa cao hướng tới phân phối theo nhu cầu."},{"code":"131120II","number":19,"question":"Đâu không phải là nội dung kinh tế của liên minh giữa giai cấp công nhân với giai cấp nông dân và các tầng lớp lao động khác trong cách mạng XHCN?","options":{"A":"Xây dựng hệ thống chính sách phát triển nông nghiệp, nông dân, nông thôn","B":"Ứng dụng khoa học kỹ thuật vào sản xuất nông nghiệp","C":"Xây dựng hệ thống chính sách an sinh xã hội","D":"Thực hiện hợp đồng kinh tế giữa doanh nghiệp nhà nước và nông dân"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"An sinh xã hội thuộc nội dung văn hóa - xã hội của liên minh, không phải nội dung kinh tế; các phương án còn lại trực tiếp gắn với sản xuất và quan hệ kinh tế."},{"code":"131120II","number":20,"question":"Điền vào chỗ trống: “Trước sự liên minh của các đại biểu khoa học, giai cấp vô sản và giới [.........], không một thế lực đen tối nào đứng vững được” (V.I.Lênin)","options":{"A":"Nông dân","B":"Kỹ thuật","C":"Doanh nhân","D":"Quân sự"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Câu nói của Lenin đề cập sự liên minh giữa đại biểu khoa học, giai cấp vô sản và giới kỹ thuật; vì vậy từ cần điền là “kỹ thuật”."},{"code":"131120II","number":21,"question":"Quan hệ nào nảy sinh từ quan hệ hôn nhân và là mối quan hệ tự nhiên, là yếu tố mạnh mẽ nhất gắn kết các thành viên trong gia đình với nhau?","options":{"A":"Hôn nhân","B":"Huyết thống","C":"Nuôi dưỡng","D":"Cả B và C"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Quan hệ huyết thống nảy sinh từ quan hệ hôn nhân, là quan hệ tự nhiên giữa các thế hệ và tạo sự gắn kết mạnh mẽ giữa các thành viên; do đó B đúng."},{"code":"131120II","number":22,"question":"Tư tưởng xã hội chủ nghĩa được hình thành gắn liền với chế độ xã hội nào?","options":{"A":"Chế độ tư bản chủ nghĩa","B":"Chế độ chiếm hữu nô lệ","C":"Chế độ công xã nguyên thủy","D":"Chế độ phong kiến"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tư tưởng xã hội chủ nghĩa xuất hiện rõ từ xã hội chiếm hữu nô lệ khi xã hội đã phân chia giai cấp và có áp bức, bóc lột; công xã nguyên thủy chưa có đối kháng giai cấp."},{"code":"131120II","number":23,"question":"“Sự xuất hiện của hình thái kinh tế - xã hội CSCN ở các nước tư bản có trình độ phát triển trung bình và những nước thuộc địa sau khi được giải phóng” là quan điểm của ai?","options":{"A":"Ph.Ăngghen","B":"C.Mác","C":"V.I.Lênin","D":"Hồ Chí Minh"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Lenin phát triển lý luận về khả năng quá độ lên chủ nghĩa xã hội ở những nước tư bản phát triển trung bình và các nước thuộc địa sau giải phóng, nên C đúng."},{"code":"131120II","number":24,"question":"Tác phẩm nào được V.I.Lênin đánh giá là “tác phẩm chủ yếu và cơ bản trình bày chủ nghĩa xã hội khoa học”?","options":{"A":"Tư bản","B":"Tuyên ngôn Đảng cộng sản","C":"Ba nguồn gốc và ba bộ phận hợp thành chủ nghĩa Mác","D":"Nguồn gốc gia đình, chế độ tư hữu và Nhà nước"},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Giáo trình dẫn cách đánh giá của Lênin dành cho bộ Tư bản của Mác."},{"code":"131120II","number":25,"question":"Phát kiến nào của C. Mác và Ăngghen đã khắc phục một cách triệt để những hạn chế có tính lịch sử của chủ nghĩa xã hội – không tưởng?","options":{"A":"Chủ nghĩa duy vật lịch sử","B":"Học thuyết về giá trị thặng dư","C":"Học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân","D":"Tính hai mặt của lao động sản xuất hàng hóa"},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Học thuyết về sứ mệnh lịch sử thế giới của giai cấp công nhân xác định lực lượng xã hội thực hiện chuyển biến cách mạng."},{"code":"131120II","number":26,"question":"“Giai cấp vô sản không thể hoàn thành sứ mệnh lịch sử nếu không tổ chức ra chính đảng của giai cấp mình” – là luận điểm được trình bày trong tác phẩm nào?","options":{"A":"Tuyên ngôn Đảng cộng sản","B":"Tình cảnh giai cấp công nhân Anh","C":"Những nguyên tắc của Chủ nghĩa cộng sản","D":"Đấu tranh giai cấp ở Pháp 1848-1850"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tuyên ngôn của Đảng Cộng sản khẳng định giai cấp vô sản phải tổ chức thành một chính đảng độc lập để thực hiện thắng lợi sứ mệnh lịch sử; vì vậy A."},{"code":"131120II","number":27,"question":"Theo V.I.Lênin, hệ thống chuyên chính vô sản ở nước Nga bao gồm:","options":{"A":"Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và tổ chức công đoàn","B":"Chính quyền Xô viết + trật tự ở đường sắt Phổ + kỹ thuật và cách thức tổ chức các tơ rớt ở Mỹ + ngành giáo dục quốc dân Mỹ","C":"Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và quốc tế cộng sản","D":"Đảng Bônsêvic lãnh đạo và liên minh công nhân – nông dân – trí thức"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong các phương án, A mô tả đúng cấu trúc cơ bản của hệ thống chuyên chính vô sản ở Nga: Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và các tổ chức quần chúng như công đoàn tham gia; B là công thức về tổ chức xây dựng kinh tế, không phải hệ thống chuyên chính."},{"code":"131120II","number":28,"question":"Theo V.I.Lênin, để dần dần cải tiến chế độ sở hữu của các nhà tư bản hạng trung và hạng nhỏ thành sở hữu công cộng, cần phải sử dụng rộng rãi hình thức kinh tế nào?","options":{"A":"Tư bản cho vay","B":"Tư bản tư nhân","C":"Tư bản thân hữu","D":"Tư bản nhà nước"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Lenin chủ trương sử dụng rộng rãi chủ nghĩa tư bản nhà nước như một hình thức quá độ để từng bước cải biến sở hữu tư nhân vừa và nhỏ theo hướng xã hội chủ nghĩa, nên D."},{"code":"131120II","number":29,"question":"C.Mác và Ph.Ăngghen coi sự chuyển biến từ hình thái kinh tế - xã hội thấp lên hình thái kinh tế - xã hội cao là:","options":{"A":"Một quá trình lịch sử","B":"Một quá trình lịch sử - tự nhiên","C":"Một quá trình tự nhiên","D":"Một quá trình phát triển văn hoá - xã hội"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo quan điểm duy vật lịch sử, sự thay thế hình thái kinh tế – xã hội diễn ra trong những điều kiện lịch sử cụ thể và theo các quy luật khách quan, nên được gọi là quá trình lịch sử – tự nhiên."},{"code":"131120II","number":30,"question":"Nhân tố quan trọng hàng đầu bảo đảm thắng lợi của sự nghiệp đổi mới, hội nhập và phát triển ở nước ta là:","options":{"A":"Phát huy vai trò làm chủ của nhân dân","B":"Đảm bảo liên minh công – nông – trí thức","C":"Giữ vững và tăng cường vai trò lãnh đạo của Đảng cộng sản Việt Nam","D":"Xây dựng Nhà nước pháp quyền XHCN"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách trình bày của môn học, giữ vững và tăng cường vai trò lãnh đạo của Đảng Cộng sản Việt Nam là nhân tố quan trọng hàng đầu bảo đảm thắng lợi của đổi mới, hội nhập và phát triển."},{"code":"131120II","number":31,"question":"Căn cứ vào tính chất quyền lực, Nhà nước sẽ bao gồm những chức năng nào?","options":{"A":"Chức năng kinh tế, chính trị, văn hoá, xã hội","B":"Chức năng đối nội và đối ngoại","C":"Chức năng giai cấp và chức năng xã hội","D":"Cả A, B, C đều đúng"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Nếu căn cứ vào tính chất của quyền lực nhà nước thì chức năng được chia thành chức năng giai cấp và chức năng xã hội; đối nội/đối ngoại là cách chia theo phạm vi, còn kinh tế/chính trị/văn hóa-xã hội là theo lĩnh vực."},{"code":"131120II","number":32,"question":"Yếu tố quyết định giai cấp nông dân không thể đảm nhận sứ mệnh lịch sử thực hiện việc chuyển biến từ xã hội TBCN lên XHCN:","options":{"A":"Họ không có hệ tư tưởng riêng độc lập","B":"Họ mang tính tư hữu cao","C":"Họ không đại diện cho phương thức sản xuất tiến bộ","D":"Họ không có chính Đảng riêng độc lập"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Nông dân không đại diện cho phương thức sản xuất tiên tiến và hiện đại nên theo lý luận của môn học không thể giữ vai trò lãnh đạo quá trình chuyển từ chủ nghĩa tư bản lên chủ nghĩa xã hội; C là nguyên nhân quyết định."},{"code":"131120II","number":33,"question":"Hình thức dân chủ quân sự xuất hiện trong xã hội nào?","options":{"A":"Tư bản chủ nghĩa","B":"Chiếm hữu nô lệ","C":"Phong kiến","D":"Công xã nguyên thuỷ"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Dân chủ quân sự là hình thức dân chủ sơ khai xuất hiện ở giai đoạn cuối của xã hội công xã nguyên thủy, trước khi nhà nước và nền dân chủ chủ nô hình thành; vì vậy D."},{"code":"131120II","number":34,"question":"Nội dung cốt lõi trong chính sách tôn giáo của Đảng và Nhà nước ta là gì?","options":{"A":"Nâng cao trách nhiệm của cả hệ thống chính trị","B":"Vấn đề theo đạo và truyền đạo","C":"Tăng cường đại đoàn kết dân tộc","D":"Công tác vận động quần chúng"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tài liệu Chương 6 xác định nội dung cốt lõi của công tác/chính sách tôn giáo là công tác vận động quần chúng, nên D đúng."},{"code":"131120II","number":35,"question":"Biện pháp nào không đúng để phát triển kinh tế trong thời kỳ quá độ lên CNXH bỏ qua chế độ tư bản chủ nghĩa?","options":{"A":"Thực hiện nhất quán lâu dài nền kinh tế nhiều thành phần trong đó kinh tế nhà nước là chủ đạo.","B":"Phát triển nền sản xuất hàng hoá theo cơ chế thị trường.","C":"Dựa trên một hình thức phân phối là phân phối theo lao động.","D":"Thông qua chế độ hợp tác tự nguyện dẫn dắt nông dân đi lên CNXH."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Thời kỳ quá độ tồn tại nhiều hình thức phân phối tương ứng với nhiều thành phần và hình thức sở hữu; vì vậy “chỉ dựa trên một hình thức phân phối theo lao động” là không đúng."},{"code":"131120II","number":36,"question":"Như thế nào là chế độ hôn nhân tiến bộ?","options":{"A":"Hôn nhân tự nguyện","B":"Một vợ một chồng, bình đẳng","C":"Được đảm bảo về pháp lý","D":"Cả A, B và C."},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Hôn nhân tiến bộ gồm ba yêu cầu gắn bó: tự nguyện; một vợ một chồng và vợ chồng bình đẳng; kết hôn, ly hôn được pháp luật bảo đảm. Vì A, B, C đều đúng nên chọn D."},{"code":"131120II","number":37,"question":"Ở nước ta, tổ chức nào hoạt động theo phương thức hiệp thương dân chủ, phối hợp và thống nhất hành động giữa các thành viên theo chương trình hoạt động chung:","options":{"A":"Đảng Cộng sản Việt Nam","B":"Chính phủ","C":"Quốc hội","D":"Mặt trận Tổ quốc Việt Nam"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Mặt trận Tổ quốc Việt Nam hoạt động theo phương thức hiệp thương dân chủ, phối hợp và thống nhất hành động giữa các thành viên."},{"code":"131120II","number":38,"question":"Yếu tố nào quyết định sự liên minh giai cấp công nhân với giai cấp nông dân và tầng lớp trí thức?","options":{"A":"Do có những lợi ích cơ bản thống nhất với nhau","B":"Do giai cấp công nhân mong muốn","C":"Do mục tiêu về chính trị của giai cấp công nhân","D":"Do có cùng một kẻ thù là giai cấp tư sản"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Liên minh công nhân - nông dân - trí thức có cơ sở khách quan từ những lợi ích cơ bản thống nhất và nhu cầu gắn kết các lĩnh vực kinh tế - xã hội; không phải chỉ do mong muốn chủ quan hay cùng một kẻ thù."},{"code":"131120II","number":39,"question":"Đảng Cộng sản Việt Nam ra đời là sự kết hợp của:","options":{"A":"Chủ nghĩa Mác – Lênin, phong trào công nhân và phong trào yêu nước","B":"Chủ nghĩa Mác – Lênin, phong trào công nhân","C":"Chủ nghĩa Mác – Lênin, phong trào công nhân và tư tưởng Hồ Chí Minh","D":"Chủ nghĩa Mác – Lênin, phong trào công nhân và phong trào chống thực dân"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Ở Việt Nam, Đảng Cộng sản ra đời từ sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước; đây là nét đặc thù so với công thức chung."},{"code":"131120II","number":40,"question":"Theo quy định của giai cấp cầm quyền trong nền dân chủ chủ nô, “nhân dân” là:","options":{"A":"Chủ nô, tăng lữ, thương gia và một số trí thức","B":"Giai cấp chủ nô và nô lệ","C":"Thương gia và nô lệ","D":"Tăng lữ và một số trí thức"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong nền dân chủ chủ nô, khái niệm “nhân dân” theo quy định của giai cấp cầm quyền chỉ bao gồm những người tự do như chủ nô, tăng lữ, thương gia và một số trí thức, không bao gồm nô lệ; A phù hợp nhất."},{"code":"2223II","number":1,"question":"Chọn đáp án đúng nhất. Ý thức hệ tiên tiến của giai cấp công nhân là:","options":{"A":"Chủ nghĩa Mác – Lênin","B":"Chủ nghĩa Mác – Lênin, tư tưởng Hồ Chí Minh","C":"Chủ nghĩa Mác – Lênin, tư tưởng dân chủ tư sản tiến bộ","D":"Không có đáp án nào đúng"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Theo cách trình bày của đề, chủ nghĩa Mác – Lênin là nền tảng lý luận và thế giới quan của giai cấp công nhân. Cách liệt kê trong lựa chọn B có thể đúng ở bối cảnh Việt Nam, nên cần chú ý phạm vi câu hỏi."},{"code":"2223II","number":2,"question":"Khái niệm “Chuyên chính của giai cấp công nhân” được sử dụng lần đầu tiên trong tác phẩm nào?","options":{"A":"Hệ tư tưởng Đức","B":"Những nguyên lý của CNCS","C":"Nội chiến ở Pháp","D":"Tuyên ngôn của Đảng Cộng Sản"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Đề gốc đánh dấu Tuyên ngôn của Đảng Cộng sản. Đây là văn kiện trình bày quan điểm đấu tranh giai cấp và vai trò lịch sử của giai cấp vô sản; nhận định về 'lần đầu tiên' cần đối chiếu văn bản gốc khi dùng để nghiên cứu."},{"code":"2223II","number":3,"question":"Nội dung chính yếu, nổi bật, thể hiện sứ mệnh lịch sử của giai cấp công nhân Việt Nam hiện nay về phương diện chính trị - xã hội là:","options":{"A":"Giữ vững bản chất giai cấp của Nhà nước, vai trò tiên phong, gương mẫu của cán bộ","B":"Giữ vững bản chất giai cấp của Đảng","C":"Giữ vững và tăng cường sự lãnh đạo của Đảng","D":"Không có đáp án đúng"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Phương diện chính trị – xã hội nhấn mạnh vai trò nhà nước, vai trò tiên phong của đội ngũ cán bộ và việc bảo vệ bản chất giai cấp; đề chọn nội dung này làm trọng tâm."},{"code":"2223II","number":4,"question":"Phát kiến này của C. Mác và Ăngghen đã khắc phục một cách triệt để những hạn chế có tính lịch sử của CNXH không tưởng phê phán, đồng thời luận chứng và khẳng định về phương diện chính trị - xã hội sự diệt vong không tránh khỏi của CNTB và sự thắng lợi tất yếu của CNXH","options":{"A":"Học thuyết về chủ nghĩa duy vật biện chứng","B":"Học thuyết về chủ nghĩa duy vật lịch sử","C":"Học thuyết về giá trị thặng dư","D":"Học thuyết về sứ mệnh lịch sử của giai cấp công nhân"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Học thuyết về sứ mệnh lịch sử của giai cấp công nhân chỉ ra lực lượng xã hội có khả năng thực hiện sự chuyển biến từ chủ nghĩa tư bản sang chủ nghĩa xã hội."},{"code":"2223II","number":5,"question":"Đặc điểm chủ yếu của giai cấp công nhân Việt Nam ở đầu thế kỷ XX là:","options":{"A":"Làm chủ quá trình sản xuất","B":"Quy mô lớn và chất lượng giai cấp công nhân cao","C":"Số lượng giai cấp công nhân Việt Nam khi ra đời còn ít, những đặc tính của công nhân","D":"Tất cả các đáp án đều đúng"},"key":"C","basis":"Đánh dấu * trong đề nguồn","reason":"Giai cấp công nhân Việt Nam hình thành trong hoàn cảnh thuộc địa, với số lượng ban đầu nhỏ và nền công nghiệp còn hạn chế."},{"code":"2223II","number":6,"question":"Liên minh giữa công nhân, nông dân và trí thức ở Việt Nam trong thời kỳ quá độ lên chủ nghĩa xã hội có thuận lợi nào","options":{"A":"Công nhân và trí thức đa số xuất thân từ nông dân","B":"Nông dân đại diện cho nền sản xuất nhỏ","C":"Số lượng giai cấp công nhân ít","D":"Trí thức không có hệ tư tưởng riêng"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Nguồn gốc xã hội gần gũi giữa công nhân, nông dân và một bộ phận trí thức tạo điều kiện thuận lợi cho sự liên minh trên cơ sở lợi ích chung."},{"code":"2223II","number":7,"question":"Đặc điểm của thời kỳ quá độ lên chủ nghĩa xã hội trên lĩnh vực xã hội là gì?","options":{"A":"Thời kỳ quá độ lên chủ nghĩa xã hội về phương diện xã hội là thời kỳ đấu tranh giai cấp","B":"Thời kỳ quá độ lên chủ nghĩa xã hội về phương diện xã hội là thời kỳ đấu tranh giai cấp","C":"Thời kỳ quá độ lên chủ nghĩa xã hội về phương diện xã hội là thời kỳ đấu tranh giai cấp chống áp bức, bất công, xóa bỏ tệ nạn xã hội và những tàn dư của xã hội cũ để lại, thiết lập công bằng xã hội trên cơ sở thực hiện nguyên tắc phân phối theo năng lực là chủ đạo","D":"Thời kỳ quá độ lên chủ nghĩa xã hội về phương diện xã hội là thời kỳ đấu tranh giai cấp chống áp bức, bất công, xóa bỏ tệ nạn xã hội và những tàn dư của xã hội cũ để lại, thiết lập công bằng xã hội trên cơ sở thực hiện nguyên tắc phân phối theo vị trí – việc làm là chủ đạo"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Đề nguồn đánh dấu phương án A, nhưng các phương án có nội dung lặp và bị rút ngắn. Chưa đủ cơ sở phân biệt đầy đủ giữa các lựa chọn; cần đối chiếu bản đề rõ hơn."},{"code":"2223II","number":8,"question":"Chủ nghĩa xã hội là một chế độ xã hội tốt đẹp,… của hình thái kinh tế - xã hội của cộng sản chủ nghĩa","options":{"A":"Giai đoạn kết thúc","B":"Giai đoạn quá độ","C":"Giai đoạn sau","D":"Giai đoạn đầu"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Theo lý luận hình thái kinh tế – xã hội cộng sản chủ nghĩa, chủ nghĩa xã hội được xem là giai đoạn thấp, trước giai đoạn cộng sản chủ nghĩa phát triển cao."},{"code":"2223II","number":9,"question":"Luận điểm nào sau đây là phương hướng cơ bản phản ánh con đường quá độ lên chủ nghĩa xã hội ở nước ta? Chọn câu trả lời ĐÚNG","options":{"A":"Tất cả các đáp án trên","B":"Xây dựng nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân và vì","C":"Xây dựng nền dân chủ xã hội chủ nghĩa, thực hiện đại đoàn kết dân tộc, tăng cường và","D":"Đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước gắn với phát triển kinh tế tri thức,"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Đề chọn phương án tổng hợp vì xây dựng nhà nước pháp quyền, phát triển dân chủ và công nghiệp hóa đều thuộc các phương hướng xây dựng chủ nghĩa xã hội được liệt kê."},{"code":"2223II","number":10,"question":"Luận điểm nào sau đây KHÔNG phải là phương hướng cơ bản phản ánh con đường quá độ lên chủ nghĩa xã hội ở nước ta?","options":{"A":"Xây dựng nhà nước pháp quyền xã hội chủ nghĩa của dân, do dân và vì dân","B":"Xây dựng nền dân chủ xã hội chủ nghĩa, thực hiện đại đoàn kết dân tộc, tăng cường và","C":"Xây dựng xã hội dân chủ, công bằng, văn minh","D":"Xây dựng Đảng trong sạch vững mạnh"},"key":"C","basis":"Đánh dấu * trong đề nguồn","reason":"'Dân chủ, công bằng, văn minh' mô tả đặc trưng hoặc mục tiêu xã hội; khác với các giải pháp và phương hướng tổ chức thực hiện được liệt kê ở các lựa chọn còn lại."},{"code":"2223II","number":11,"question":"Thực chất của quan hệ liên minh công – nông – tri thức là:","options":{"A":"Quan hệ chính trị - xã hội","B":"Quan hệ kinh tế - xã hội","C":"Quan hệ tư tưởng – xã hội","D":"Quan hệ văn hóa – xã hội"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Theo đáp án đề nguồn, liên minh công nhân, nông dân và trí thức thể hiện quan hệ hợp tác chính trị – xã hội. Tuy nhiên, cần phân biệt bản chất liên minh với nội dung kinh tế là cơ sở quan trọng của liên minh."},{"code":"2223II","number":12,"question":"Đặc điểm sự chênh lệch về dân số giữa các tộc người của dân tộc Việt Nam được thể hiện ở tiêu chí","options":{"A":"Chất lượng dân số","B":"Mật độ dân cư","C":"Phân bố dân cư","D":"Số lượng cư dân"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"'Chênh lệch về dân số' trực tiếp nói đến số lượng người của mỗi tộc người, không phải mật độ, chất lượng hay sự phân bố theo lãnh thổ."},{"code":"2223II","number":13,"question":"Tín đồ các tôn giáo Việt Nam phần lớn là đối tượng nào?","options":{"A":"Không có đáp án đúng","B":"Là những người lao động chân tay","C":"Là những người lao động trí óc","D":"Nhân dân lao động"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Trong bối cảnh Việt Nam, các cộng đồng tín đồ tôn giáo bao gồm đông đảo người dân lao động, không chỉ riêng lao động chân tay hay lao động trí óc."},{"code":"2223II","number":14,"question":"Đặc trưng cơ bản nhất của dân tộc, quốc gia là đặc trưng nào?","options":{"A":"Có chung phương thức sinh hoạt","B":"Có lãnh thổ chung ổn định không bị chia cắt, có sự quản lý của một Nhà nước","C":"Có ngôn ngữ chung","D":"Có nét văn hóa riêng"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Đề đánh dấu A. Tuy nhiên, khái niệm dân tộc theo nghĩa quốc gia thường gồm nhiều dấu hiệu về lãnh thổ, kinh tế, nhà nước; lựa chọn A tương đối khái quát, cần kiểm tra lại định nghĩa trong giáo trình môn học."},{"code":"2223II","number":15,"question":"Chính sách dân tộc của Đảng và Nhà nước ta mang tính chất như thế nào?","options":{"A":"Cục bộ trên một số lĩnh vực","B":"Phiến diện, cục bộ trên mọi lĩnh vực","C":"Toàn diện, sâu sắc trên mọi lĩnh vực","D":"Toàn diện, tổng hợp trên mọi lĩnh vực"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Chính sách dân tộc được triển khai qua nhiều mặt như kinh tế, chính trị, văn hóa và xã hội, nên không giới hạn trong một lĩnh vực riêng lẻ."},{"code":"2223II","number":16,"question":"Với 2 phát kiến này C.Mác và Ph.Angghen đã đưa CNXH từ không tưởng trở thành khoa học","options":{"A":"Học thuyết giá trị thặng dư – học thuyết sứ mệnh lịch sử của giai cấp công nhân","B":"Học thuyết về Chủ nghĩa duy vật biện chứng – Học thuyết về sứ mệnh lịch sử của giai cấp công nhân","C":"Học thuyết về Chủ nghĩa duy vật lịch sử - Học thuyết giá trị thặng dư","D":"Học thuyết về chủ nghĩa duy vật lịch sử - học thuyết về sứ mệnh lịch sử của giai cấp công nhân"},"key":"C","basis":"Đánh dấu * trong đề nguồn","reason":"Chủ nghĩa duy vật lịch sử giải thích quy luật vận động của xã hội; học thuyết giá trị thặng dư phân tích cơ sở kinh tế của sự bóc lột trong chủ nghĩa tư bản. Đây là hai phát kiến mà đề đang nhấn mạnh."},{"code":"2223II","number":17,"question":"Chọn đáp án đúng “Với phát kiến này C. Mác đã đưa lý luận chủ nghĩa xã hội từ khoa học trở thành thực tiễn sinh động”","options":{"A":"Chủ nghĩa duy vật lịch sử.","B":"Học thuyết giá trị","C":"Học thuyết giá trị thặng dư","D":"Học thuyết về sứ mệnh lịch sử của giai cấp công nhân"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Học thuyết sứ mệnh lịch sử của giai cấp công nhân xác định chủ thể xã hội có vai trò thực hiện sự chuyển biến cách mạng; đó là lý do đề gắn lý luận với hoạt động thực tiễn."},{"code":"2223II","number":18,"question":"Chủ nghĩa xã hội là gì?","options":{"A":"Cả 3 đáp án trên đều đúng","B":"Là một khoa học – Chủ nghĩa xã hội khoa học","C":"Là phong trào thực tiễn, phong trào đấu tranh của nhân dân lao động chống các giai cấp thống trị","D":"Là trào lưu tư tưởng, lý luận phản ánh lý tưởng giải phóng nhân dân lao động khỏi áp bức, bóc lột, bất công"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Trong phạm vi khái niệm rộng, chủ nghĩa xã hội có thể được xét như hệ tư tưởng, phong trào thực tiễn và lý luận khoa học, nên các cách mô tả ở B, C, D cùng được tính đến."},{"code":"2223II","number":19,"question":"Những tư tưởng xã hội chủ nghĩa không tưởng phê phán còn không ít những hạn chế do?","options":{"A":"Những điều kiện lịch sử","B":"Sự hạn chế về thế giới quan của những nhà tư tưởng","C":"Sự hạn chế về tầm nhìn của những nhà tư tưởng","D":"Tất cả các phương án đều đúng"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Những nhà tư tưởng xã hội chủ nghĩa không tưởng bị giới hạn bởi hoàn cảnh lịch sử và điều kiện nhận thức của thời đại, nên chưa chỉ ra cơ chế hiện thực để thay đổi xã hội."},{"code":"2223II","number":20,"question":"Ai đã đưa ra nhận xét: “Chủ nghĩa xã hội không tưởng không thể vạch ra được lối thoát thực sự”","options":{"A":"C.Mác","B":"C.Mác và Ph.Ăngghen","C":"Ph.Ăngghen","D":"V.Lênin"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Đề ghi nhận phát biểu này là nhận xét của V.I. Lênin về hạn chế của chủ nghĩa xã hội không tưởng; cần đối chiếu tác phẩm gốc nếu sử dụng như một trích dẫn học thuật."},{"code":"2223II","number":21,"question":"C.Mác sinh năm bao nhiêu?","options":{"A":"1818","B":"1820","C":"1883","D":"191"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Karl Marx (C. Mác) sinh năm 1818, vì vậy phương án A là mốc năm đúng."},{"code":"2223II","number":22,"question":"Một số giải pháp xây dựng giai cấp công nhân Việt Nam hiện nay là:","options":{"A":"Tăng cường quan hệ đoàn kết, hợp tác quốc tế với giai cấp công nhân trên thế giới","B":"Tất cả các đáp án trên đều đúng","C":"Xây dựng giai cấp công nhân lớn mạnh là trách nhiệm của cả hệ thống chính trị, của toàn xã hội và sự nỗ lực vươn lên của bản thân mỗi người công nhân, sự tham gia đóng góp tích cực của người sử dụng lao động","D":"Đào tạo, bồi dưỡng, nâng cao trình độ mọi mặt cho công nhân, không ngừng tri thức hóa giai cấp công nhân. Đặc biệt quan tâm xây dựng thế hệ công nhân ngang tầm khu vực và quốc tế, có lập trường giai cấp và bản lĩnh chính trị vững vàng"},"key":"B","basis":"Đánh dấu * trong đề nguồn","reason":"Các biện pháp nêu ở A, C, D đều hỗ trợ phát triển năng lực, vị thế và sự đoàn kết của giai cấp công nhân Việt Nam, nên đề chọn phương án tổng hợp."},{"code":"2223II","number":23,"question":"Phương hướng xây dựng giai cấp công nhân Việt Nam hiện nay là:","options":{"A":"Chú trọng xây dựng, phát huy vai trò của giai cấp công nhân, giai cấp nông dân, đội ngũ tri thức, đội ngũ doanh nhân đáp ứng yêu cầu phát triển đất nước trong thời kỳ mới","B":"Tất cả các đáp án đều đúng","C":"Xây dựng giai cấp công nhân có tinh thần đoàn kết dân tộc, đoàn kết, hợp tác quốc tế","D":"Xây dựng giai cấp công nhân lớn mạnh, phát triển nhanh về số lượng"},"key":"B","basis":"Đánh dấu * trong đề nguồn","reason":"Các nội dung phát triển số lượng, chất lượng và tăng cường đoàn kết công nhân có tính bổ trợ, do đó tài liệu lựa chọn phương án tổng hợp."},{"code":"2223II","number":24,"question":"Chọn đáp án đúng nhất: Vấn đề nổi bật nhất về nội dung sứ mệnh lịch sử của giai cấp công nhân Việt Nam khi thực hiện nội dung Kinh tế là:","options":{"A":"Giai cấp công nhân phát huy vai trò và trách nhiệm lực lượng đi đầu trong sự nghiệp","B":"Giai cấp công nhân phát huy vai trò và trách nhiệm trong sự nghiệp đẩy mạnh công","C":"Giai cấp công nhân thực hiện công nghiệp hóa, hiện đại hóa nông nghiệp nông thôn","D":"Giai cấp công nhân thực hiện xây dựng hoàn chỉnh về quan hệ sản xuất, tạo nền tảng"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Về phương diện kinh tế, giai cấp công nhân được xem là lực lượng đi đầu trong công nghiệp hóa, hiện đại hóa; các lựa chọn ở đề có đoạn bị cắt, nên cần đối chiếu bản đầy đủ để khẳng định cách diễn đạt."},{"code":"2223II","number":25,"question":"Đảng cộng sản là đại biểu trung thành cho lợi ích của:","options":{"A":"Giai cấp công nhân.","B":"Giai cấp công nhân, dân tộc và xã hội","C":"Giai cấp lãnh đạo","D":"Giai cấp nông dân"},"key":"B","basis":"Đánh dấu * trong đề nguồn","reason":"Trong bối cảnh chính trị Việt Nam, Đảng được xác định đại diện cho lợi ích của giai cấp công nhân, nhân dân lao động và dân tộc; lựa chọn B là cách diễn đạt bao quát nhất trong đề."},{"code":"2223II","number":26,"question":"Dân chủ là gì?","options":{"A":"Quyền lực cho giai cấp chiếm số đông trong xã hội","B":"Quyền lực cho giai cấp thống trị","C":"Quyền lực cho giai cấp áp đảo trong xã hội","D":"Quyền lực thuộc về nhân dân"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Dân chủ có gốc nghĩa quyền lực thuộc về nhân dân, vì vậy không thể chỉ đồng nhất với quyền lực của một nhóm thống trị."},{"code":"2223II","number":27,"question":"Đặc điểm của nền dân chủ XHCN là gì?","options":{"A":"Dân chủ với số đông những người lao động trong xã hội","B":"Hoàn bị nhất trong lịch sử.","C":"Phát triển cao nhất trong lịch sử","D":"Tuyệt đối nhất trong lịch sử"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Theo lý luận dân chủ xã hội chủ nghĩa, quyền tham gia quản lý xã hội được mở rộng cho đông đảo nhân dân lao động, không có nghĩa là tồn tại một nền dân chủ tuyệt đối không hạn chế."},{"code":"2223II","number":28,"question":"Các nhận định sau đây, nhận định nào đúng về tính tất yếu của liên minh giữa giai cấp công nhân với giai cấp nông dân và tầng lớp trí thức trong thời kỳ quá độ lên CNXH:","options":{"A":"Nhằm chống lại sự thống trị của giai cấp tư sản","B":"Vì công nhân, nông dân, tri thức đều là những giai cấp lãnh đạo xã hội","C":"Vì họ đều bị bóc lột","D":"Xuất phát từ mối liên hệ tự nhiên, gắn bó và sự thống nhất về lợi ích của các giai cấp, tầng lớp xã hội đó quy định"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Liên minh giữa công nhân, nông dân và trí thức được lý giải từ mối liên hệ khách quan và sự thống nhất lợi ích, không phải vì tất cả các nhóm đều có cùng vị thế lãnh đạo."},{"code":"2223II","number":29,"question":"Trong thời kỳ quá độ lên CNXH, cơ cấu xã hội – giai cấp bao gồm các giai cấp, tầng lớp sau:","options":{"A":"Công nhân, nông dân và trí thức","B":"Công nhân, nông dân và trí thức và các tầng lớp nhân dân lao động khác","C":"Công nhân, nông dân, trí thức, tư sản, tiểu tư sản và các tầng lớp nhân dân lao động khác","D":"Phong kiến, công nhân, nông dân, trí thức, tư sản, tiểu tư sản"},"key":"C","basis":"Đánh dấu * trong đề nguồn","reason":"Trong thời kỳ quá độ tồn tại nhiều giai cấp và tầng lớp xã hội, không chỉ công nhân, nông dân và trí thức; phương án C phản ánh phạm vi rộng hơn."},{"code":"2223II","number":30,"question":"“Nguyên tắc cao nhất của chuyên chính là duy trì khối liên minh giữa giai cấp vô sản và nông dân để giai cấp vô sản có thể giữ được vai trò lãnh đạo và chính quyền nhà nước” là luận điểm của ai?","options":{"A":"C.Mác","B":"C.Mác và Ph.Ăngghen","C":"Ph.Ăngghen","D":"V.Lênin"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Đề gốc quy luận điểm về duy trì liên minh công – nông để giữ vai trò lãnh đạo của giai cấp vô sản cho V.I. Lênin."},{"code":"2223II","number":31,"question":"Cần phải xây dựng khối liên minh giữa giai cấp công nhân với giai cấp nông dân và các tầng lớp nhân dân lao động khác vì","options":{"A":"Tất cả những yêu cầu nêu trên","B":"Yêu cầu giải phóng triệt để giai cấp nông dân và nhân dân lao động.","C":"Yêu cầu thực hiện thắng lợi sứ mệnh lịch sử của giai cấp công nhân","D":"Yêu cầu xây dựng Nhà nước vững mạnh của giai cấp công nhân"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Xây dựng liên minh phục vụ nhiều mục tiêu liên hệ nhau: phát huy sứ mệnh lịch sử của công nhân, giải phóng người lao động và củng cố bộ máy nhà nước."},{"code":"2223II","number":32,"question":"Chọn câu trả lời đúng: Trong thời kỳ quá độ lên CNXH, cơ cấu xã hội – giai cấp do","options":{"A":"Cơ cấu kinh tế quy định","B":"Do chế độ chính trị quy định","C":"Do giai cấp lãnh đạo quy định","D":"Do quan hệ sở hữu về TLSX quy định"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Cơ cấu kinh tế quyết định về cơ bản sự biến đổi cơ cấu xã hội – giai cấp thông qua quan hệ sản xuất, sở hữu và phân công lao động."},{"code":"2223II","number":33,"question":"Chọn đáp án đúng: Cơ cấu xã hội – giai cấp là","options":{"A":"Khác","B":"Là hệ thống các giai cấp, tầng lớp xã hội tồn tại khách quan trong một chế độ xã hội nhất định","C":"Là hệ thống các giai cấp, tầng lớp xã hội tồn tại khách quan trong một chế độ xã hội nhất định, thông qua những mối quan hệ về sở hữu, về tổ chức quản lý quá trình sản xuất, về địa vị chính trị - xã hội… giữa các giai cấp, tầng lớp đó","D":"Là những mối quan hệ về sở hữu, về tổ chức quản lý quá trình sản xuất, về địa vị chính trị - xã hội giữa các giai cấp, tầng lớp"},"key":"C","basis":"Đánh dấu * trong đề nguồn","reason":"Cơ cấu xã hội – giai cấp không chỉ là danh sách các nhóm người mà còn gồm quan hệ về sở hữu, tổ chức sản xuất và địa vị chính trị – xã hội giữa các nhóm."},{"code":"2223II","number":34,"question":"Chọn đáp án đúng: Cơ cấu xã hội là","options":{"A":"Là cơ cấu giai cấp trong xã hội","B":"Là cơ cấu kinh tế trong xã hội","C":"Là cộng đồng người cùng toàn bộ những mối quan hệ xã hội","D":"Là những cộng đồng người cùng toàn bộ những mối quan hệ xã hội do sự tác động lẫn nhau của các cộng đồng ấy tạo nên"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Định nghĩa cơ cấu xã hội phải bao gồm các cộng đồng người và toàn bộ quan hệ nảy sinh từ tác động qua lại giữa họ; D đầy đủ hơn A, B, C."},{"code":"2223II","number":35,"question":"Chọn đáp án đúng: Dưới góc độ chính trị -xã hội. Môn chủ nghĩa xã hội khoa học tập trung nghiên cứu.","options":{"A":"Cơ cấu xã hội - dân cư","B":"Cơ cấu xã hội - dân tộc","C":"Cơ cấu xã hội - giai cấp","D":"Cơ cấu xã hội - tôn giáo"},"key":"C","basis":"Đánh dấu * trong đề nguồn","reason":"CNXHKH tập trung nghiên cứu quan hệ giai cấp và sự biến đổi cơ cấu xã hội – giai cấp từ góc độ chính trị – xã hội."},{"code":"2223II","number":36,"question":"Chọn đáp án ĐÚNG về đặc trưng của xã hội XHCN mà nhân dân xây dựng:.","options":{"A":"Các dân tộc trong cộng đồng Việt Nam bình đẳng, đoàn kết, tôn trọng và giúp nhau cùng phát triển","B":"Các dân tộc trong cộng đồng Việt Nam có quan hệ hữu nghị, hợp tác với nhau và với các nước trên thế giới","C":"Các dân tộc trong cộng đồng Việt Nam độc lập, có quan hệ hợp tác trong các lĩnh vực kinh tế, chính trị, văn hóa, xã hội","D":"Dân tộc Việt Nam và các dân tộc trên thế giới bình đẳng, đoàn kết và giúp nhau cùng phát triển"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Đặc trưng xã hội xã hội chủ nghĩa được văn kiện Việt Nam mô tả bằng quan hệ bình đẳng, đoàn kết, tôn trọng và hỗ trợ phát triển giữa các dân tộc trong cộng đồng."},{"code":"2223II","number":37,"question":"Chọn phương án trả lời chính xác: ở phương Tây, dân tộc xuất hiện khi nào?","options":{"A":"Phương thức sản xuất phong kiến thay thế phương thức sản xuất chiếm hữu nô lệ","B":"Phương thức sản xuất phong kiến thay thế phương thức sản xuất tư bản chủ nghĩa","C":"Phương thức sản xuất tư bản chủ nghĩa thay thế phương thức sản xuất chiếm hữu nô lệ","D":"Phương thức sản xuất tư bản chủ nghĩa thay thế phương thức sản xuất phong kiến"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Ở phương Tây, sự hình thành dân tộc hiện đại gắn với sự phát triển thị trường thống nhất và quan hệ sản xuất tư bản chủ nghĩa thay thế trật tự phong kiến."},{"code":"2223II","number":38,"question":"Việc thực hiện quyền dân tộc tự quyết trong cương lĩnh dân tộc của Lênin phải đứng vững trên lập trường của giai cấp nào?","options":{"A":"Giai cấp công nhân","B":"Giai cấp nông dân","C":"Giai cấp tư bản","D":"Tầng lớp trí thức"},"key":"A","basis":"Đánh dấu * trong đề nguồn","reason":"Trong cách tiếp cận của Lênin, quyền dân tộc tự quyết được xem xét gắn với lợi ích chung của phong trào công nhân và quan hệ giữa các dân tộc."},{"code":"2223II","number":39,"question":"Trong cương lĩnh dân tộc, quyền tự quyết của các dân tộc có ý nghĩa là:","options":{"A":"Các dân tộc có quyền tự lựa chọn chế độ chính trị và con đường phát triển của dân tộc mình","B":"Các dân tộc tự quyết định vận mệnh dân tộc của mình","C":"Các dân tộc tự quyết định vận mệnh dân tộc mình, quyền tự lựa chọn chế độ chính trị và con đường phát triển của dân tộc mình","D":"Các dân tộc đều có nghĩa vụ và quyền lợi ngang nhau"},"key":"C","basis":"Đánh dấu * trong đề nguồn","reason":"Tự quyết dân tộc bao gồm khả năng lựa chọn chế độ chính trị và định hướng phát triển của cộng đồng dân tộc; C diễn đạt đầy đủ các ý hơn A và B."},{"code":"2223II","number":40,"question":"Chọn câu trả lời chính xác nhất về tôn giáo:","options":{"A":"Tôn giáo là một hình thái ý thức xã hội phản ánh hiện thực chủ quan","B":"Tôn giáo là một hình thái ý thức xã hội phản ánh hiện thực chủ quan","C":"Tôn giáo là một hình thái ý thức xã hội phản ánh hiện thực khách quan","D":"Tôn giáo là một hình thái ý thức xã hội phản ánh hư ảo hiện thực khách quan"},"key":"D","basis":"Đánh dấu * trong đề nguồn","reason":"Theo cách tiếp cận duy vật lịch sử, tôn giáo là một hình thái ý thức xã hội phản ánh hiện thực khách quan qua hình ảnh siêu nhiên, hư ảo, chứ không phải phản ánh trực tiếp như khoa học."},{"code":"DE-ON-01","number":1,"question":"Nhà tư tưởng xã hội chủ nghĩa nào đã tổ chức thực hiện khu vực cộng sản trong long xã hội tư bản?","options":{"A":"Xanh Xi Mông.","B":"Rô Bớc Ô Oen.","C":"Phu Ri Ê.","D":"Ba Bớp."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Robert Owen là nhà xã hội chủ nghĩa không tưởng đã trực tiếp tổ chức các mô hình thực nghiệm cộng sản trong lòng xã hội tư bản, tiêu biểu ở New Lanark; vì vậy chọn B."},{"code":"DE-ON-01","number":2,"question":"Tính tất yếu của cách mạng xã hội chủ nghĩa trên lĩnh vực tư tưởng và văn hóa xuất phát từ căn cứ nào?","options":{"A":"Xuất phát từ cuộc đấu tranh giai cấp trên lĩnh vực tư tưởng và văn hóa trong thời đại ngày nay.","B":"Xuất phát từ yêu cầu không ngừng nâng cao đời sống vật chất của nhân dân lao động.","C":"Xuất phát từ yêu cầu giải quyết các mối quan hệ quốc tế.","D":"Cả ba đều đúng."},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tính tất yếu của cách mạng trên lĩnh vực tư tưởng - văn hóa trước hết xuất phát từ cuộc đấu tranh giai cấp vẫn diễn ra trên chính lĩnh vực này; B nói về đời sống vật chất còn C nói về quan hệ quốc tế nên không đúng trọng tâm."},{"code":"DE-ON-01","number":3,"question":"Các nhà tư tưởng xã hội chủ nghĩa trước Mác với hạn chế cơ bản là gì?","options":{"A":"Không chủ trương xóa bỏ chế độ tư hữu về tư liệu sản xuất.","B":"Không chủ trương xóa bỏ chế độ người bóc lột người.","C":"Không thể phát hiện ra được lực lượng xã hội tiên phong thực hiện cuộc chuyển biến cách mạng xã hội.","D":"Mong muốn thực hiện chế độ bình quân trong phân phối."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Hạn chế căn bản của chủ nghĩa xã hội không tưởng là chưa xác định được lực lượng xã hội tiên phong có khả năng thực hiện cuộc chuyển biến cách mạng, tức chưa nhận ra đầy đủ vai trò lịch sử của giai cấp công nhân."},{"code":"DE-ON-01","number":4,"question":"Tiền đề kinh tế cho sự hình thành tư tưởng xã hội chủ nghĩa là?","options":{"A":"Sự xuất hiện giai cấp thống trị.","B":"Sự xuất hiện nhà nước.","C":"Sự xuất hiện chế độ tư hữu.","D":"Cả a, b, c đều đúng."},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Trong các tiền đề được nêu, sự xuất hiện chế độ tư hữu là điều kiện kinh tế của tư tưởng xã hội chủ nghĩa."},{"code":"DE-ON-01","number":5,"question":"Tư tưởng xã hội chủ nghĩa được hình thành gắn liền với chế độ xã hội nào?","options":{"A":"Chế độ công xã nguyên thủy.","B":"Chế độ chiếm hữu nô lệ.","C":"Chế độ phong kiến.","D":"Chế độ tư bản chủ nghĩa."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tư tưởng xã hội chủ nghĩa xuất hiện rõ từ xã hội chiếm hữu nô lệ khi xã hội đã phân chia giai cấp và có áp bức, bóc lột; công xã nguyên thủy chưa có đối kháng giai cấp."},{"code":"DE-ON-01","number":6,"question":"Chủ nghĩa xã hội khoa học là học thuyết được xây dựng trên cơ sở thế giới quan triết học nào?","options":{"A":"Chủ nghĩa duy tâm chủ quan.","B":"Chủ nghĩa duy tâm khách quan.","C":"Chủ nghĩa duy vật siêu hình.","D":"Chủ nghĩa duy vật biện chứng."},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chủ nghĩa xã hội khoa học được xây dựng trên thế giới quan và phương pháp luận của chủ nghĩa duy vật biện chứng, không dựa trên chủ nghĩa duy tâm hay duy vật siêu hình."},{"code":"DE-ON-01","number":7,"question":"C.Mác và Ph.Ăngghen đã luận giải một cách khoa học và cách mạng về vai trò lãnh đạo của Đảng Cộng sản trong tác phẩm nào?","options":{"A":"Gia đình thần thánh.","B":"Hệ tư tưởng Đức.","C":"Tuyên ngôn của Đảng Cộng sản.","D":"Tình cảnh giai cấp lao động ở Anh."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tuyên ngôn của Đảng Cộng sản trình bày vai trò chính trị của giai cấp vô sản và sự cần thiết của tổ chức đảng trong cuộc đấu tranh giải phóng giai cấp."},{"code":"DE-ON-01","number":8,"question":"Bộ phận thể hiện tập trung nhất tính chính trị - thực tiễn sinh động của chủ nghĩa Mác:","options":{"A":"Triết học Mác.","B":"Kinh tế chính trị Mác.","C":"Chủ nghĩa xã hội khoa học.","D":"Chủ nghĩa xã hội nhân văn."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong ba bộ phận của chủ nghĩa Mác - Lênin, chủ nghĩa xã hội khoa học trực tiếp nghiên cứu con đường, lực lượng và phương pháp cải biến xã hội nên thể hiện tập trung nhất tính chính trị - thực tiễn."},{"code":"DE-ON-01","number":9,"question":"Chủ nghĩa xã hội khoa học ra đời từ điều kiện kinh tế - xã hội nào?","options":{"A":"Phương thức sản xuất tư bản chủ nghĩa phát triển mạnh mẽ gắn liền với nền đại công nghiệp.","B":"Phương thức sản xuất tư bản chủ nghĩa gắn liền với công trường thủ công.","C":"Sự ra đời của giai cấp công nhân.","D":"Sự ra đời của Đảng cộng sản."},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chủ nghĩa xã hội khoa học ra đời khi phương thức sản xuất tư bản chủ nghĩa phát triển mạnh trên nền đại công nghiệp, làm mâu thuẫn xã hội và phong trào công nhân phát triển."},{"code":"DE-ON-01","number":10,"question":"Chủ nghĩa xã hội khoa học đã làm sáng tỏ vai trò lịch sử toàn thế giới của giai cấp nào?","options":{"A":"Giai cấp nông dân.","B":"Giai cấp công nhân.","C":"Giai cấp tư sản.","D":"Giai cấp chủ nô."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chủ nghĩa xã hội khoa học làm sáng tỏ vai trò lịch sử toàn thế giới của giai cấp công nhân; các giai cấp còn lại không được xác định giữ sứ mệnh này."},{"code":"DE-ON-01","number":11,"question":"Thời gian nào đánh dấu sự ra đời của chủ nghĩa xã hội khoa học?","options":{"A":"Ngày 22 tháng 2 năm 1848.","B":"Ngày 23 tháng 2 năm 1848.","C":"Ngày 24 tháng 2 năm 1848.","D":"Ngày 25 tháng 2 năm 1848."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách ra đáp án của đề này, chọn C - ngày 24/2/1848. Tuy nhiên, bảy tài liệu lý thuyết của môn chỉ chốt mốc năm 1848 gắn với Tuyên ngôn của Đảng Cộng sản, nên khi ôn cần nhớ chắc mốc 1848."},{"code":"DE-ON-01","number":12,"question":": Chọn cụm từ thí ch hợp điền vào ô trống: V.I.Lênin đã viết: “… có thể thắng lợi ở một số nước hay thậm chí ở một nước riêng lẻ, nơi chủ nghĩa tư bản chưa phải là phát triển nhất, nhưng là khâu yếu nhất trong sợi dây chuyền tư bản chủ nghĩa”","options":{"A":"Cách mạng xã hội.","B":"Cách mạng tư bản.","C":"Cách mạng vô sản.","D":"Cách mạng chủ nghĩa."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Lenin phát triển quan điểm về khả năng cách mạng vô sản thắng lợi trước ở một hoặc một số nước, kể cả nơi không phát triển nhất nhưng là khâu yếu của hệ thống tư bản chủ nghĩa; vì vậy chọn C."},{"code":"DE-ON-01","number":13,"question":"Chủ nghĩa xã hội khoa học có nhiệm vụ cơ bản là:","options":{"A":"Luận chứng một cách khoa học tính tất yếu về mặt lịch sử sự thay thế của chủ nghĩa tư bản bằng chủ nghĩa xã hội với sứ mệnh lịch sử của giai cấp tư sản.","B":"Luận chứng một cách khoa học tính tất yếu về mặt lịch sử sự thay thế của chủ nghĩa tư bản bằng chủ nghĩa cộng sản với sứ mệnh lịch sử của giai tư sản.","C":"Luận chứng một cách khoa học tính tất yếu về mặt lịch sử sự thay thế của chủ nghĩa tư bản bằng chủ nghĩa xã hội với sứ mệnh lịch sử của giai cấp công nhân.","D":"Luận chứng một cách khoa học tính tất yếu về mặt lịch sử sự thay thế của chủ nghĩa xã hội bằng chủ nghĩa cộng sản với sứ mệnh lịch sử của giai cấp công nhân."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Nhiệm vụ cơ bản là luận chứng khoa học tính tất yếu chủ nghĩa tư bản được thay thế bằng chủ nghĩa xã hội và làm rõ sứ mệnh lịch sử của giai cấp công nhân; C nêu đủ cả hai vế."},{"code":"DE-ON-01","number":14,"question":"Theo nghĩa chung nhất dân chủ là gì?","options":{"A":"Là quyền lực cho giai cấp chiếm số đông trong xã hội.","B":"Là quyền lực thuộc về nhân dân.","C":"Là quyền tự do của mỗi người.","D":"Quyền lực cho giai cấp cầm quyền."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Đáp án B đúng vì nghĩa chung nhất của dân chủ là quyền lực thuộc về nhân dân; đây cũng là nghĩa gốc của khái niệm dân chủ."},{"code":"DE-ON-01","number":15,"question":"Nền dân chủ XHCN mang bản chất của giai cấp nào?","options":{"A":"Giai cấp công nhân và quần chúng nhân dân lao động.","B":"Giai cấp công nhân.","C":"Giai cấp chiếm đa số.","D":"Công nhân và nông dân."},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Xét về bản chất giai cấp, nền dân chủ XHCN mang bản chất giai cấp công nhân, đồng thời có tính nhân dân rộng rãi."},{"code":"DE-ON-01","number":16,"question":"Kiểu nhà nước nào sau đây được Lênin gọi là nhà nước “ Nửa nhà nước”?","options":{"A":"Nhà nước Chủ nô.","B":"Nhà nước tư sản.","C":"Nhà nước phong kiến.","D":"Nhà nước xã hội chủ nghĩa."},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Lenin gọi nhà nước xã hội chủ nghĩa là “nửa nhà nước” vì chức năng trấn áp có xu hướng giảm, trong khi chức năng tổ chức và xây dựng xã hội mới ngày càng tăng."},{"code":"DE-ON-01","number":17,"question":"Bản chất của nhà nước xã hội chủ nghĩa là gì?","options":{"A":"Mang bản chất của giai cấp công nhân.","B":"Mang bản chất của đa số nhân dân lao động.","C":"Mang bản chất của giai cấp công nhân, tính nhân dân rộng rãi và tính dân tộc sâu sắc.","D":"Vừa mang bản chất của giai cấp công nhân, vừa mang bản chất của nhân dân lao động và tính dân tộc sâu sắc."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Đáp án C đúng vì bản chất nhà nước xã hội chủ nghĩa được trình bày ở ba mặt gắn bó: bản chất giai cấp công nhân, tính nhân dân rộng rãi và tính dân tộc sâu sắc."},{"code":"DE-ON-01","number":18,"question":"Trong lịch sử loài người đã từng xuất hiện các chế độ dân chủ nào sau đây?","options":{"A":"Chủ nô, phong kiến, tư sản, vô sản.","B":"Chủ nô, tư sản, vô sản.","C":"Công xã nguyên thủy, chủ nô, phong kiến, tư sản, vô sản.","D":"Chủ nô, phong kiến, tư sản."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Xét các chế độ dân chủ gắn với kiểu nhà nước, giáo trình nêu dân chủ chủ nô, dân chủ tư sản và dân chủ vô sản/xã hội chủ nghĩa; xã hội phong kiến chủ yếu tổ chức theo quân chủ."},{"code":"DE-ON-01","number":19,"question":"Điền vào chỗ trống: Khái niệm dân tộc “dùng để chỉ một cộng đồng người có liên hệ chặt chẽ và bền vững, ….., xuất hiện sau bộ lạc, bộ tộc, kế thừa và phát triển cao hơn những nhân tố tộc người ở bộ lạc, bộ tộc và thể hiện thành ý thức tự giác tộc người của dân cư cộng đồng đó.”","options":{"A":"Sinh sống trên cùng một lãnh thổ, có gần huyết thống.","B":"Có chung sinh hoạt kinh tế, có ngôn ngữ riêng, văn hóa có những đặc thù.","C":"Có cùng nguồn gốc tổ tiên, cùng chung ngôn ngữ.","D":"Có ý thức về sự thống nhất của mình."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Mô tả này là dân tộc theo nghĩa hẹp - tộc người: có chung sinh hoạt kinh tế, ngôn ngữ riêng, nét văn hóa đặc thù và ý thức tự giác tộc người."},{"code":"DE-ON-01","number":20,"question":"Chọn đáp án đúng","options":{"A":"Dân tộc là một bộ phận của quốc gia.","B":"Dân tộc là toàn bộ nhân dân của quốc gia đó.","C":"Dân tộc và quốc gia là hai khái niệm đồng nhất.","D":"a và b đúng."},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Từ “dân tộc” có cả nghĩa tộc người và cộng đồng quốc gia–dân tộc; hai mô tả A và B thuộc hai phạm vi."},{"code":"DE-ON-01","number":21,"question":"Yếu tố nào sau đây là cơ sở để liên kết các bộ phận, các thành viên của dân tộc. Nó tạo nên nền tảng cho sự vững chắc của cộng đồng dân tộc.","options":{"A":"Có chung sinh hoạt về kinh tế.","B":"Có chung ngôn ngữ.","C":"Có chung văn hóa, tâm lý, lãnh thổ.","D":"Có chung lãnh thổ."},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Sinh hoạt kinh tế chung tạo ra những mối liên hệ vật chất thường xuyên giữa các thành viên, là nền tảng bền vững để cộng đồng dân tộc gắn kết."},{"code":"DE-ON-01","number":22,"question":"Điền vào chỗ trống: “Chủ nghĩa Mác – Lênin coi tín ngưỡng, tôn giáo là ….. phản ánh một cách hoang đường, hư ảo hiện thực khách quan. Thông qua sự phản ánh đó, các lực lượng tự nhiên trở thành siêu tự nhiên, thàn bí”","options":{"A":"Một thực thể thần thánh.","B":"Một tư duy huyền bí.","C":"Một hình thái ý thức.","D":"Một ý niệm tuyệt đối."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo chủ nghĩa Mác - Lênin, tôn giáo là một hình thái ý thức xã hội phản ánh hiện thực khách quan một cách hư ảo, nên C đúng."},{"code":"DE-ON-01","number":23,"question":"Có bao nhiêu nguồn gốc cho sự ra đời của tôn giáo, là những nguồn gốc nào?","options":{"A":"1, nguồn gốc tư duy huyền thoại.","B":"2, nguồn gốc kinh tế - xã hội, nguồn gốc nhận thức.","C":"3, nguồn gốc kinh tế - xã hội, nguồn gốc nhận thức, nguồn gốc tâm lý.","D":"4, nguồn gốc tư duy huyền thoại, nguồn gốc kinh tế xã hội, nguồn gốc nhận thức, nguồn gốc tâm lý."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Ba nguồn gốc cơ bản của tôn giáo là kinh tế - xã hội, nhận thức và tâm lý; phải phân biệt ba nguồn gốc này với ba tính chất hoặc năm chức năng của tôn giáo."},{"code":"DE-ON-01","number":24,"question":"Nội dung cốt lõi của công tác tôn giáo ở nước ta trong giai đoạn hiện nay là?","options":{"A":"Là công tác vận động quần chúng.","B":"Là phát huy vai trò của các cơ quan quản lý tôn giáo.","C":"Là phát huy vai trò của chức sắc tôn giáo.","D":"Cả a, b và c."},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Công tác vận động quần chúng là nội dung cốt lõi của công tác tôn giáo."},{"code":"DE-ON-01","number":25,"question":"Người ta có thể nhận biết điều gì qua sinh hoạt vật chất, cũng như sinh hoạt tinh thần của dân tộc ấy, đặc biệt là qua các phong tục tập quán, tín ngưỡng, đời sống văn hóa?","options":{"A":"Trình độ phát triển của dân tộc.","B":"Tâm lý, tính cách của một dân tộc.","C":"Bản chất con người của dân tộc.","D":"Năng lực sản xuất."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Phong tục, tập quán, tín ngưỡng và đời sống văn hóa biểu hiện những nét tâm lý, tính cách riêng của một dân tộc; vì vậy chọn B."},{"code":"DE-ON-01","number":26,"question":"Trong một quốc gia có nhiều dân tộc cần thiết nên?","options":{"A":"Tập trung phát triển văn hóa của dân tộc nổi trội nhất làm định hướng cho các dân tộc còn lại.","B":"Xóa nhòa khắc biệt về bản sắc văn hóa các dân tộc, để các dân tộc đồng đẳng.","C":"Bảo tồn giá trị văn hóa của tất cả các dân tộc, tạo ra sự thống nhất trong đa dạng bản sắc văn hóa các dân tộc.","D":"Tất cả đều đúng."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong quốc gia đa dân tộc phải bảo tồn bản sắc của từng dân tộc đồng thời xây dựng sự thống nhất trong đa dạng; không thể đồng hóa hoặc xóa nhòa bản sắc."},{"code":"DE-ON-01","number":27,"question":"Tôn giáo có mấy tính chất? là những tính chất nào?","options":{"A":"3 tính chất, gồm: tính lịch sử, tính quần chúng và tính chính trị.","B":"4 tính chất, gồm: tính lịch sử, tính quần chúng, tính chính trị và tính triết lý.","C":"5 tính chất, gồm: đền bù hư ảo, thế giới quan, điều chỉnh hành vi, giao tiếp, liên kết cộng đồng.","D":"6 tính chất, gồm: triết lý, đền bù hư ảo, thế giới quan, điều chỉnh hành vi, giao tiếp, liên kết cộng đồng."},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Ba tính chất cơ bản thường được giáo trình trình bày là tính lịch sử, tính quần chúng và tính chính trị."},{"code":"DE-ON-01","number":28,"question":"Chọn đáp án sai","options":{"A":"Tôn trọng tự do tín ngưỡng là tôn trọng quyền tự do tư tưởng.","B":"Tôn trọng quyền tự do tín ngưỡng là tôn trọng quyền con người.","C":"Tôn trọng quyền tự do tín ngưỡng là tôn trọng và chấp nhận giáo lý của tất cả các tôn giáo.","D":"Tôn trọng quyền tự do tín ngưỡng thể hiện bản chất ưu việt của chế độ xã hội chủ nghĩa."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tôn trọng tự do tín ngưỡng không có nghĩa nhà nước hoặc mọi cá nhân phải chấp nhận toàn bộ giáo lý của tất cả tôn giáo; đó là tôn trọng quyền lựa chọn niềm tin của con người, nên C là phát biểu sai."},{"code":"DE-ON-01","number":29,"question":"Có bao nhiêu mối quan hệ cơ bản được xem là cơ sở hình thành gia đình? Đó là những mối quan hệ nào?","options":{"A":"1, là quan hệ hôn thú.","B":"2, là quan hệ hôn nhân và quan hệ huyết thống.","C":"3, là quan hệ hôn nhân, quan hệ huyết thống, quan hệ kinh tế.","D":"4, là quan hệ hôn nhân, quan hệ huyết thống, quan hệ kinh tế, quan hệ hôn thú."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách phân loại cơ bản trong giáo trình, hai quan hệ nền tảng hình thành gia đình là quan hệ hôn nhân và quan hệ huyết thống; ngoài ra thực tế còn có quan hệ nuôi dưỡng."},{"code":"DE-ON-01","number":30,"question":"Chức năng nào sau đây đảm bảo tái sản xuất nguồn lao động và sức lao động cho xã hội","options":{"A":"Chức năng nuôi dưỡng, giáo dục.","B":"Chức năng kinh tế.","C":"Chức năng tái sản xuất ra con người.","D":"Chức năng thỏa mãn các nhu cầu tâm sinh lý, duy trì tình cảm."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chức năng tái sản xuất con người duy trì các thế hệ mới, qua đó tái tạo dân số, nguồn lao động và sức lao động cho xã hội."},{"code":"DE-ON-01","number":31,"question":"Chức năng nào sau đây của gia đình ảnh hưởng lâu dài và toàn diện đối với mỗi cá nhân trong cuộc đời, từ lúc còn bé cho đến khi trưởng thành và tuổi già?","options":{"A":"Chức năng tái sản xuất con người.","B":"Chức năng cầu nối giữa cá nhân với xã hội.","C":"Chức năng nuôi dưỡng, giáo dục.","D":"Chức năng thỏa mãn các nhu cầu tâm sinh lý, duy trì tình cảm."},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Chức năng nuôi dưỡng và giáo dục tác động lâu dài đến phát triển thể chất, trí tuệ, nhân cách của cá nhân."},{"code":"DE-ON-01","number":32,"question":"Gia đình phải thực hiện chức năng nào để đảm bảo nguồn sinh sống, đáp ứng nhu cầu vật chất, tinh thần của các thành viên trong gia đình?","options":{"A":"Chức năng kinh tế, tổ chức tiêu dùng.","B":"Chức năng tái sản xuất con người.","C":"Chức năng nuôi dưỡng, giáo dục.","D":"Chức năng thỏa mãn các nhu cầu tâm sinh lý, duy trì tình cảm."},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chức năng kinh tế và tổ chức tiêu dùng giúp gia đình tạo, phân phối và sử dụng nguồn lực để đáp ứng nhu cầu vật chất và tinh thần của các thành viên."},{"code":"DE-ON-01","number":33,"question":"Gia đình Việt Nam hiện nay có sự biến đổi về quy mô như thế nào?","options":{"A":"Có xu hướng thu nhỏ lại.","B":"Có xu hướng phình to ra.","C":"Có xu hướng ổn định không thay đổi so với trước đây.","D":"Tồn tại cả 3 xu hướng trên."},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Gia đình Việt Nam hiện nay có xu hướng thu nhỏ về quy mô, gia đình hạt nhân phổ biến hơn do điều kiện kinh tế - xã hội và lối sống thay đổi."},{"code":"DE-ON-01","number":34,"question":"Nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam là nhà nước pháp quyền mang bản chất:","options":{"A":"Giai cấp nông dân, tính nhân dân và tính dân tộc.","B":"Giai cấp tư sản, tính nhân dân và tính dân tộc.","C":"Giai cấp công nhân, tính nhân dân và tính dân tộc.","D":"Tính nhân dân rộng rãi."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Nhà nước pháp quyền xã hội chủ nghĩa Việt Nam mang bản chất giai cấp công nhân, đồng thời có tính nhân dân rộng rãi và tính dân tộc sâu sắc; C diễn đạt đúng ba mặt."},{"code":"DE-ON-01","number":35,"question":"Nền dân chủ XHCN dựa trên cơ sở kinh tế nào?","options":{"A":"Kinh tế nhiều thành phần.","B":"Công hữu về tư liệu sản xuất.","C":"Tư hữu về tư liệu sản xuất .","D":"Kinh tế xã hội chủ nghĩa."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Cơ sở kinh tế của dân chủ xã hội chủ nghĩa là chế độ công hữu/sở hữu xã hội đối với tư liệu sản xuất chủ yếu, nên B phù hợp nhất."},{"code":"DE-ON-01","number":36,"question":"Điền từ vào chỗ trống: Nhà nước xã hội chủ nghĩa vừa có bản chất giai cấp công nhân, vừa có tính nhân dân rộng rãi và tính …………sâu sắc.","options":{"A":"Giai cấp.","B":"Nhân đạo.","C":"Dân tộc.","D":"Cộng đồng."},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Nhà nước XHCN được mô tả có tính dân tộc sâu sắc bên cạnh bản chất giai cấp và tính nhân dân."},{"code":"DE-ON-01","number":37,"question":"So với các nền dân chủ trước đây, dân chủ xã hội chủ nghĩa có điểm khác biệt cơ bản nào?","options":{"A":"Không còn mang tính giai cấp.","B":"Là nền dân chủ mang tính lịch sử.","C":"Là nền dân chủ tuyệt đối.","D":"Là nền dân chủ rộng rãi cho giai cấp công nhân và nhân dân lao động."},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Đáp án D đúng vì điểm khác biệt cơ bản được nhấn mạnh là dân chủ xã hội chủ nghĩa mở rộng quyền làm chủ cho giai cấp công nhân và đông đảo nhân dân lao động, thay vì dân chủ chủ yếu phục vụ thiểu số sở hữu."},{"code":"DE-ON-01","number":38,"question":"Điền từ còn thiếu vào chỗ trống: “Nước ta là nước dân chủ, nghĩa là nước nhà do nhân dân làm chủ. Nhân dân có quyền lợi làm chủ, thì phải có … làm tròn bổn phận công dân” (Hồ Chí Minh)","options":{"A":"Trách nhiệm.","B":"Nghĩa vụ.","C":"Trình độ để.","D":"Khả năng để."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Câu nói của Hồ Chí Minh gắn quyền làm chủ với nghĩa vụ công dân: có quyền lợi làm chủ thì phải có nghĩa vụ làm tròn bổn phận công dân."},{"code":"DE-ON-01","number":39,"question":"Điền vào ô trống từ còn thiếu: “Quyền không bao giờ có thể ở một mức độ cao hơn chế độ … và sự phát triển văn hoá của xã hội do chế độ … đó quyết định” (Mác: Phê phán Cương lĩnh Gôta)","options":{"A":"Chính trị.","B":"Xã hội.","C":"Kinh tế.","D":"Nhà nước."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong Phê phán Cương lĩnh Gôta, Marx chỉ ra quyền không thể cao hơn chế độ kinh tế và trình độ phát triển văn hóa do chế độ kinh tế đó quyết định; vì vậy chọn C."},{"code":"DE-ON-01","number":40,"question":"Nhà nước pháp quyền xã hội chủ nghĩa quản lý mọi mặt của đời sống xã hội chủ yếu bằng gì?","options":{"A":"Đường lối, chính sách.","B":"Hiến pháp, pháp luật.","C":"Tuyên truyền, giáo dục.","D":"Cả a, b và c."},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Nhà nước pháp quyền quản lý xã hội chủ yếu thông qua Hiến pháp và pháp luật."},{"code":"DE-ON-01","number":41,"question":"Khẳng định nào dưới đây đứng về nội dung dân chủ trong lĩnh vực văn hóa?","options":{"A":"Công dân được tham gia vào đời sống văn hóa.","B":"Công dân được kiến nghị với các cơ quan nhà nước.","C":"Công dân bình đẳng về cống hiến và hưởng thụ.","D":"Công dân tham gia vào các phong trào xã hội ở địa phương."},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Quyền tham gia vào đời sống văn hóa là biểu hiện trực tiếp của dân chủ trên lĩnh vực văn hóa; kiến nghị với nhà nước thuộc chính trị còn phong trào địa phương thiên về xã hội."},{"code":"DE-ON-01","number":42,"question":"Nền dân chủ XHCN dựa trên hệ tư tưởng nào?","options":{"A":"Hệ tư tưởng của giai cấp công nhân, nông dân và tri thức.","B":"Hệ tư tưởng của chủ nghĩa Mác-Lênin.","C":"Hệ tư tưởng của giai cấp tư sản.","D":"Hệ tư tưởng của trí thức."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Nền dân chủ xã hội chủ nghĩa dựa trên hệ tư tưởng chủ nghĩa Mác - Lênin; đây là nền tảng tư tưởng chứ không phải sự pha trộn hệ tư tưởng của nhiều giai cấp."},{"code":"DE-ON-01","number":43,"question":"Dân chủ XHCN được thực hiện trên những lĩnh vực nào?","options":{"A":"Trên lĩnh vực chính trị.","B":"Trên lĩnh vực kinh tế, chính trị, văn hóa - xã hội.","C":"Trên lĩnh vực kinh tế, chính trị.","D":"Văn hóa, tinh thần."},"key":"B","basis":"Giải và đối chiếu thêm","reason":"Nền dân chủ XHCN thể hiện trên các lĩnh vực chính trị, kinh tế, văn hóa và xã hội."},{"code":"DE-ON-01","number":44,"question":"Phạm trù (khái niệm) dân chủ xuất hiện khi nào?","options":{"A":"Ngay từ khi có xã hội loài người.","B":"Khi có nhà nước vô sản.","C":"Khi có chế độ tư hữu, giai cấp và nhà nước.","D":"Trong xã hội công xã nguyên thủy."},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Theo cách tiếp cận lịch sử trong giáo trình, hình thức dân chủ ban đầu gắn với xã hội công xã nguyên thủy."},{"code":"DE-ON-01","number":45,"question":"Đặc điểm của nền dân chủ XHCN.","options":{"A":"Phát triển cao nhất so với các nền dân chủ khác trong lịch sử.","B":"Là nền dân chủ cho mọi giai cấp.","C":"Tuyệt đối nhất trong lịch sử.","D":"Không mang tính giai cấp."},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Phương án A phản ánh cách đánh giá sự phát triển dân chủ XHCN trong hệ thống lý luận môn học."},{"code":"DE-ON-01","number":46,"question":"Bản chất chính trị của nền dân chủ xã hội chủ nghĩa thể hiện như thế nào?","options":{"A":"Là sự lãnh đạo của giai cấp công nhân thông qua đảng của nó đối với toàn xã hội, để thực hiện quyền lực và lợi ích của toàn thể nhân dân lao động, trong đó có giai cấp công nhân.","B":"Là thực hiện quyền lực của giai cấp công nhân và nhân dân lao động đối với toàn xã hội.","C":"Là sự lãnh đạo của giai cấp công nhân thông qua chính đảng của nó để cải tạo xã hội cũ và xây dựng xã hội mới.","D":"Cả a, b và c."},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Bản chất chính trị: sự lãnh đạo của giai cấp công nhân thông qua đảng đối với toàn xã hội nhằm thực hiện lợi ích của đông đảo nhân dân."},{"code":"DE-ON-01","number":47,"question":"Khái niệm “Hệ thống chính trị xã hội chủ nghĩa” do tổ chức nào sau đây nêu ra?","options":{"A":"Đảng Cộng sản Liên Xô.","B":"Đảng Cộng sản Trung Quốc.","C":"Đảng Cộng sản Việt Nam.","D":"Quốc tế cộng sản (Quốc tế III)."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách ra đáp án của bộ đề này, chọn C - Đảng Cộng sản Việt Nam. Bảy tài liệu lý thuyết hiện có không trình bày riêng lịch sử xuất hiện thuật ngữ này, nên đây là câu cần ghi nhớ theo nguồn đề."},{"code":"DE-ON-01","number":48,"question":"Câu nào sau đây sai?","options":{"A":"Quan hệ huyết thống là cơ sở cho sự hình thành và tồn tại của một gia đình.","B":"Quan hệ huyết thống nảy sinh từ quan hệ hôn nhân.","C":"Quan hệ huyết thống là cơ sở để duy trì hôn nhân, quan hệ hôn nhân và gia đình.","D":"Tất cả đều sai."},"key":null,"basis":"Mơ hồ / cần giảng viên xác nhận","reason":"C và D đều có thể được xem là sai: C nói huyết thống duy trì hôn nhân; D nói tất cả phát biểu đều sai, trong khi A/B có cơ sở. Vì vậy câu có khả năng đa đáp án."},{"code":"DE-ON-01","number":49,"question":"Khi đề cập đến nội dung tái sản xuất, duy trì nòi giống, nuôi dưỡng nâng cao thể lực, trí lực là muốn đề cập đến chức năng nào của gia đình?","options":{"A":"Chức năng tái sản xuất ra con người.","B":"Chức năng duy trì quyền thừa kế.","C":"Chức năng kinh tế và tổ chức đời sống gia đình.","D":"Chức năng giáo dục."},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Tái sản xuất, duy trì nòi giống là chức năng tái sản xuất con người của gia đình."},{"code":"DE-ON-01","number":50,"question":"Có bao nhiêu điều kiện xây dựng gia đình trong quá trình xây dựng chủ nghĩa xã hội?","options":{"A":"2, gồm: điều kiện chính trị và văn hóa - xã hội.","B":"3, gồm: điều kiện kinh tế - xã hội, chính trị và văn hóa - xã hội.","C":"4, gồm: điều kiện kinh tế, chính trị, văn hóa, xã hội.","D":"5, gồm: điều kiện pháp lý, kinh tế, chính trị, văn hóa, xã hội."},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách phân loại của tài liệu ôn tập, có ba nhóm điều kiện xây dựng gia đình trong thời kỳ quá độ: kinh tế – xã hội, chính trị và văn hóa – xã hội."},{"code":"DE-ON-02","number":1,"question":"Nhà nước là:","options":{"A":"Tổ chức chính trị của giai cấp thống trị về kinh tế nhằm bảo vệ trật tự hiện hành và đàn áp sự phản kháng của các giai cấp khác.","B":"Tổ chức chính trị của giai cấp thống trị về kinh tế nhằm bảo vệ trật tự hiện hành và bảo vệ lợi ích của tất cả các giai cấp khác","C":"Tổ chức chính trị đứng trên các giai cấp nhằm bảo vệ tất cả các giai cấp.","D":"Tổ chức chính trị đứng ngoài xã hội, cai trị xã hội"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo lý luận Mác - Lênin, nhà nước là tổ chức quyền lực chính trị của giai cấp thống trị về kinh tế, dùng để duy trì trật tự hiện hành và trấn áp sự phản kháng của các giai cấp đối lập; A phù hợp nhất."},{"code":"DE-ON-02","number":2,"question":"Trong cách mạng xã hội chủ nghĩa, ai được xác định là “người bạn đồng minh tự nhiên” của giai cấp công nhân?","options":{"A":"Doanh nhân","B":"Tư sản","C":"Trí thức","D":"Nông dân"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Giai cấp nông dân được xác định là “người bạn đồng minh tự nhiên” của giai cấp công nhân vì có nhiều lợi ích cơ bản gần gũi trong đấu tranh và xây dựng xã hội mới."},{"code":"DE-ON-02","number":3,"question":"Điền vào chỗ trống cho đoạn văn sau đây: “ [.........] là sản phẩm của sự kết hợp chủ nghĩa Mác – Lênin với phong trào công nhân trong cuộc đấu tranh thực hiện sứ mệnh lịch sử của giai cấp công nhân”","options":{"A":"Giai cấp công nhân","B":"Đảng Cộng sản","C":"Đảng chính trị","D":"Giai cấp tư sản"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Đảng Cộng sản là sản phẩm của sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân; đây là công thức chung về sự ra đời của chính đảng giai cấp công nhân."},{"code":"DE-ON-02","number":4,"question":"Trong thời kỳ quá độ lên chủ nghĩa xã hội, cơ cấu xã hội – giai cấp bị quy định bởi:","options":{"A":"Cơ cấu văn hóa xã hội","B":"Cơ cấu chính trị","C":"Cơ cấu nhân sự","D":"Cơ cấu kinh tế"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Cơ cấu kinh tế quy định cơ cấu xã hội – giai cấp trong thời kỳ quá độ."},{"code":"DE-ON-02","number":5,"question":"Điền vào chỗ trống: “tất cả mọi tôn giáo chẳng qua chỉ là sự phản ánh [.........] vào trong đầu óc của con người – của những lực lượng ở bên ngoài chi phối cuộc sống hàng ngày của họ”","options":{"A":"Niềm tin","B":"Hư ảo","C":"Sinh động","D":"Hiện thực"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Cụm từ kinh điển là “sự phản ánh hư ảo” các lực lượng bên ngoài chi phối đời sống con người, nên từ cần điền là “hư ảo”."},{"code":"DE-ON-02","number":6,"question":"Theo Mác và Ph.Ăngghen, có hai tiêu chí cơ bản xác định giai cấp công nhân đó là:","options":{"A":"Về phương thức lao động, phương thức sản xuất và vị trí của giai cấp công nhân trong quan hê ̣sản xuất xã hội chủ nghĩa","B":"Về phương thức lao động, phương thức sản xuất và vị trí của giai cấp công nhân trong quan hê ̣sản xuất.","C":"Về phương thức lao động, phương thức sản xuất và vị trí của giai cấp công nhân trong quan hê ̣sản xuất xã hội","D":"Về phương thức lao động, phương thức sản xuất và vị trí của giai cấp công nhân trong quan hê ̣sản xuất tư bản chủ nghĩa"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Mác và Ăngghen xét cả phương thức lao động và vị trí trong quan hệ sản xuất tư bản chủ nghĩa."},{"code":"DE-ON-02","number":7,"question":"Hạn chế cơ bản của các nhà tư tưởng xã hội chủ nghĩa không tưởng là:","options":{"A":"Không chủ trương xóa bỏ chế độ áp bức bóc lột","B":"Không thể phát hiện ra lực lượng xã hội tiên phong thực hiện cuộc chuyển biến cách mạng xã hội","C":"Mong muốn thực hiện chế độ bình quân trong phân phối","D":"Không chủ trương xóa bỏ chế độ tư hữu về tư liệu sản xuất"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Hạn chế cơ bản của chủ nghĩa xã hội không tưởng là chưa phát hiện được lực lượng xã hội tiên phong có khả năng hiện thực hóa cuộc chuyển biến cách mạng, tức vai trò của giai cấp công nhân."},{"code":"DE-ON-02","number":8,"question":"Tiền đề kinh tế cho sự hình thành tư tưởng xã hội chủ nghĩa là:","options":{"A":"Sự xuất hiện giai cấp thống trị","B":"Sự xuất hiện nhà nước","C":"Sự xuất hiện chế độ tư hữu","D":"Cả A, B và C đều đúng"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chế độ tư hữu làm nảy sinh phân hóa sở hữu, giai cấp và bóc lột; đó là tiền đề kinh tế khiến tư tưởng hướng tới một xã hội công bằng hơn xuất hiện."},{"code":"DE-ON-02","number":9,"question":"Chủ nghĩa xã hội khoa học ra đời từ điều kiện kinh tế - xã hội nào?","options":{"A":"Sự ra đời của giai cấp công nhân","B":"Phương thức sản xuất tư bản chủ nghĩa gắn liền với công trường thủ công","C":"Phương thức sản xuất tư bản chủ nghĩa phát triển mạnh mẽ gắn liền với nền đại công nghiệp","D":"Sự ra đời của Đảng cộng sản"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chủ nghĩa xã hội khoa học ra đời khi phương thức sản xuất tư bản chủ nghĩa phát triển mạnh trên nền đại công nghiệp, làm mâu thuẫn xã hội và phong trào công nhân phát triển."},{"code":"DE-ON-02","number":10,"question":"Điều kiện chủ quan quyết định sự thành công khi thực hiện sứ mệnh lịch sử của giai cấp công nhân là:","options":{"A":"Bản thân giai cấp công nhân phát triển về số lượng và chất lượng","B":"Đảng Cộng sản lãnh đạo","C":"Địa vị kinh tế - xã hội và địa vị chính trị - xã hội quy định","D":"Cả A, B"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Sự trưởng thành của giai cấp công nhân cùng vai trò lãnh đạo của Đảng là điều kiện chủ quan."},{"code":"DE-ON-02","number":11,"question":"Tôn giáo ra đời là do?","options":{"A":"Sự yếu kém của trình độ lực lượng sản xuất","B":"Sự sợ hãi trước sức mạnh của tự nhiên và xã hội","C":"Sự bần cùng của kinh tế, áp bức về chính trị","D":"Cả A, B và C đều đúng"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Các phương án nêu những nguyên nhân khách quan và nhận thức gắn với sự hình thành tôn giáo."},{"code":"DE-ON-02","number":12,"question":"Phong trào đấu tranh của giai cấp công nhân Lion (Pháp) đã chuyển từ khẩu hiệu “Sống có việc làm hay là chết trong đấu tranh” (1931) sang “Cộng hòa hay là chết” (1934) thể hiện cho sự phát triển:","options":{"A":"Từ mục đích đấu tranh chính trị sang đấu tranh văn hóa, tư tưởng","B":"Từ mục đích đấu tranh văn hóa, tư tưởng sang mục đích xóa bỏ bóc lột","C":"Từ mục đích đấu tranh kinh tế sang đấu tranh chính trị","D":"Từ mục đích đấu tranh kinh tế sang mục đích đấu tranh văn hóa, tư tưởng"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Khẩu hiệu từ đòi “việc làm” sang đòi “cộng hòa” cho thấy phong trào chuyển từ yêu sách kinh tế sang mục tiêu chính trị, nên C đúng."},{"code":"DE-ON-02","number":13,"question":"Phát kiến nào của C. Mác và Ăngghen là sự khẳng định về mặt triết học sự sụp đổ của chủ nghĩa tư bản và sự thắng lợi của chủ nghĩa xã hội đều tất yếu như nhau?","options":{"A":"Tính hai mặt của lao động sản xuất hàng hóa","B":"Học thuyết về giá trị thặng dư","C":"Học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân","D":"Chủ nghĩa duy vật lịch sử"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Chủ nghĩa duy vật lịch sử giải thích về mặt triết học quy luật vận động và thay thế các hình thái kinh tế - xã hội; giá trị thặng dư là cơ sở kinh tế, còn sứ mệnh lịch sử xác định lực lượng thực hiện."},{"code":"DE-ON-02","number":14,"question":"CNXHKH phát triển trong khoảng thời gian từ sau 1895 đến năm 1917 thuộc giai đoạn nào sau đây trong lịch sử hình thành và phát triển của CNXHKH","options":{"A":"Giai đoạn Mác và Ăngghen","B":"Giai đoạn từ sau Lênin mất","C":"Cả A,B,C đều sai","D":"Giai đoạn Lênin phát triển CNXHKH"},"key":"D","basis":"Giải và đối chiếu thêm","reason":"Giai đoạn sau năm 1895 đến 1917 thuộc thời kỳ Lênin phát triển CNXHKH."},{"code":"DE-ON-02","number":15,"question":"Bản chất của chuyên chính vô sản là:","options":{"A":"Liên kết giai cấp vô sản các dân tộc trên thế giới","B":"Trấn áp bằng bạo lực đối với giai cấp bóc lột","C":"Giai cấp công nhân đưa ra được và thực hiện được kiểu tổ chức lao động xã hội cao hơn so với chủ nghĩa tư bản","D":"Học tập chủ nghĩa tư bản về khoa học kỹ thuật, kinh nghiệm quản lý kinh tế"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Bản chất của chuyên chính vô sản không chỉ là trấn áp; điểm sâu hơn là giai cấp công nhân tổ chức được kiểu lao động xã hội cao hơn chủ nghĩa tư bản và dùng quyền lực để xây dựng xã hội mới, nên C."},{"code":"DE-ON-02","number":16,"question":"Ba trụ cột cho sự phát triển nhanh và bền vững của Việt Nam là:","options":{"A":"Phát triển kinh tế là nhiệm vụ trung tâm, xây dựng Đảng là khâu then chốt và phát triển văn hóa là nền tảng tinh thần của xã hội","B":"Phát triển kinh tế là nhiệm vụ then chốt, xây dựng Đảng là khâu trung tâm và phát triển văn hóa là nền tảng tinh thần của xã hội","C":"Phát triển kinh tế là nhiệm vụ nền tảng, xây dựng Đảng là khâu then chốt và phát triển văn hóa là trung tâm tinh thần của xã hội","D":"Phát triển kinh tế là nhiệm vụ then chốt, xây dựng Đảng là khâu trung tâm và phát triển văn hóa là nền tảng then chốt của xã hội"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách hỏi “ba trụ cột” của đề, A đúng: kinh tế là trung tâm, xây dựng Đảng là then chốt, văn hóa là nền tảng tinh thần. Lưu ý slide Chương 3 hiện tại còn bổ sung quốc phòng - an ninh thành trụ cột trọng yếu, thường xuyên."},{"code":"DE-ON-02","number":17,"question":"“Dựa trên cơ sở những tư liệu thực tiễn của lịch sử để rút ra những nhận định, những khái quát về lý luận có kết cấu chặt chẽ, khoa học” là nội dung của phương pháp nghiên cứu nào trong môn CNXHKH?","options":{"A":"Phương pháp điều tra xã hội học","B":"Phương pháp khảo sát và phân tích về mặt chính trị - xã hội","C":"Phương pháp so sánh","D":"Phương pháp kết hợp lịch sử và logic"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Phương pháp kết hợp lịch sử và logic xuất phát từ tư liệu lịch sử cụ thể rồi khái quát thành những kết luận lý luận có cấu trúc và tính quy luật; vì vậy D đúng."},{"code":"DE-ON-02","number":18,"question":"Phân phối theo lao động là hình thức phân phối cơ bản của xã hội nào?","options":{"A":"Xã hội xã hội chủ nghĩa","B":"Xã hội cộng sản chủ nghĩa","C":"Xã hội tư bản chủ nghĩa","D":"Các phương án trên đều sai"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Phân phối theo lao động là hình thức phân phối cơ bản của chủ nghĩa xã hội; giai đoạn cộng sản chủ nghĩa cao hướng tới phân phối theo nhu cầu."},{"code":"DE-ON-02","number":19,"question":"Đâu không phải là nội dung kinh tế của liên minh giữa giai cấp công nhân với giai cấp nông dân và các tầng lớp lao động khác trong cách mạng XHCN?","options":{"A":"Xây dựng hệ thống chính sách phát triển nông nghiệp, nông dân, nông thôn","B":"Ứng dụng khoa học kỹ thuật vào sản xuất nông nghiệp","C":"Xây dựng hệ thống chính sách an sinh xã hội","D":"Thực hiện hợp đồng kinh tế giữa doanh nghiệp nhà nước và nông dân"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"An sinh xã hội thuộc nội dung văn hóa - xã hội của liên minh, không phải nội dung kinh tế; các phương án còn lại trực tiếp gắn với sản xuất và quan hệ kinh tế."},{"code":"DE-ON-02","number":20,"question":"Điền vào chỗ trống: “Trước sự liên minh của các đại biểu khoa học, giai cấp vô sản và giới [.........], không một thế lực đen tối nào đứng vững được” (V.I.Lênin)","options":{"A":"Nông dân","B":"Kỹ thuật","C":"Doanh nhân","D":"Quân sự"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Câu nói của Lenin đề cập sự liên minh giữa đại biểu khoa học, giai cấp vô sản và giới kỹ thuật; vì vậy từ cần điền là “kỹ thuật”."},{"code":"DE-ON-02","number":21,"question":"Quan hệ nào nảy sinh từ quan hệ hôn nhân và là mối quan hệ tự nhiên, là yếu tố mạnh mẽ nhất gắn kết các thành viên trong gia đình với nhau?","options":{"A":"Hôn nhân","B":"Huyết thống","C":"Nuôi dưỡng","D":"Cả B và C"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Quan hệ huyết thống nảy sinh từ quan hệ hôn nhân, là quan hệ tự nhiên giữa các thế hệ và tạo sự gắn kết mạnh mẽ giữa các thành viên; do đó B đúng."},{"code":"DE-ON-02","number":22,"question":"Tư tưởng xã hội chủ nghĩa được hình thành gắn liền với chế độ xã hội nào?","options":{"A":"Chế độ tư bản chủ nghĩa","B":"Chế độ chiếm hữu nô lệ","C":"Chế độ công xã nguyên thủy","D":"Chế độ phong kiến"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tư tưởng xã hội chủ nghĩa xuất hiện rõ từ xã hội chiếm hữu nô lệ khi xã hội đã phân chia giai cấp và có áp bức, bóc lột; công xã nguyên thủy chưa có đối kháng giai cấp."},{"code":"DE-ON-02","number":23,"question":"“Sự xuất hiện của hình thái kinh tế - xã hội CSCN ở các nước tư bản có trình độ phát triển trung bình và những nước thuộc địa sau khi được giải phóng” là quan điểm của ai?","options":{"A":"Ph. Ăngghen","B":"C. Mác","C":"V.I. Lênin","D":"Hồ Chí Minh"},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Dự báo con đường phát triển CNCS từ nước tư bản phát triển trung bình và thuộc địa sau giải phóng gắn với tư tưởng Lênin."},{"code":"DE-ON-02","number":24,"question":"Tác phẩm nào được V.I.Lênin đánh giá là “tác phẩm chủ yếu và cơ bản trình bày chủ nghĩa xã hội khoa học”?","options":{"A":"Tư bản","B":"Tuyên ngôn Đảng cộng sản","C":"Ba nguồn gốc và ba bộ phận hợp thành chủ nghĩa Mác","D":"Nguồn gốc gia đình, chế độ tư hữu và Nhà nước"},"key":"A","basis":"Giải và đối chiếu thêm","reason":"Tác phẩm được Lênin nhắc đến là bộ Tư bản của Mác."},{"code":"DE-ON-02","number":25,"question":"Phát kiến nào của C. Mác và Ăngghen đã khắc phục một cách triệt để những hạn chế có tính lịch sử của chủ nghĩa xã hội – không tưởng?","options":{"A":"Chủ nghĩa duy vật lịch sử","B":"Học thuyết về giá trị thặng dư","C":"Học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân","D":"Tính hai mặt của lao động sản xuất hàng hóa"},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Học thuyết sứ mệnh lịch sử giai cấp công nhân chỉ ra chủ thể hiện thực của sự chuyển đổi xã hội."},{"code":"DE-ON-02","number":26,"question":"“Giai cấp vô sản không thể hoàn thành sứ mệnh lịch sử nếu không tổ chức ra chính đảng của giai cấp mình” – là luận điểm được trình bày trong tác phẩm nào?","options":{"A":"Tuyên ngôn Đảng cộng sản","B":"Tình cảnh giai cấp công nhân Anh","C":"Những nguyên tắc của Chủ nghĩa cộng sản","D":"Đấu tranh giai cấp ở Pháp 1848-1850"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tuyên ngôn của Đảng Cộng sản khẳng định giai cấp vô sản phải tổ chức thành một chính đảng độc lập để thực hiện thắng lợi sứ mệnh lịch sử; vì vậy A."},{"code":"DE-ON-02","number":27,"question":"Theo V.I.Lênin, hệ thống chuyên chính vô sản ở nước Nga bao gồm:","options":{"A":"Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và tổ chức công đoàn","B":"Chính quyền Xô viết + trật tự ở đường sắt Phổ + kỹ thuật và cách thức tổ chức các tơ rớt ở Mỹ + ngành giáo dục quốc dân Mỹ","C":"Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và quốc tế cộng sản","D":"Đảng Bônsêvic lãnh đạo và liên minh công nhân – nông dân – trí thức"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong các phương án, A mô tả đúng cấu trúc cơ bản của hệ thống chuyên chính vô sản ở Nga: Đảng Bônsêvic lãnh đạo, Nhà nước Xô viết quản lý và các tổ chức quần chúng như công đoàn tham gia; B là công thức về tổ chức xây dựng kinh tế, không phải hệ thống chuyên chính."},{"code":"DE-ON-02","number":28,"question":"Theo V.I.Lênin, để dần dần cải tiến chế độ sở hữu của các nhà tư bản hạng trung và hạng nhỏ thành sở hữu công cộng, cần phải sử dụng rộng rãi hình thức kinh tế nào?","options":{"A":"Tư bản cho vay","B":"Tư bản tư nhân","C":"Tư bản thân hữu","D":"Tư bản nhà nước"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Lenin chủ trương sử dụng rộng rãi chủ nghĩa tư bản nhà nước như một hình thức quá độ để từng bước cải biến sở hữu tư nhân vừa và nhỏ theo hướng xã hội chủ nghĩa, nên D."},{"code":"DE-ON-02","number":29,"question":"C.Mác và Ph.Ăngghen coi sự chuyển biến từ hình thái kinh tế - xã hội thấp lên hình thái kinh tế - xã hội cao là:","options":{"A":"Một quá trình lịch sử","B":"Một quá trình lịch sử - tự nhiên","C":"Một quá trình tự nhiên","D":"Một quá trình phát triển văn hoá - xã hội"},"key":"B","basis":"Đối chiếu ngân hàng tài liệu","reason":"Sự vận động giữa các hình thái kinh tế – xã hội vừa có tính lịch sử cụ thể vừa chịu tác động của các quy luật khách quan về lực lượng sản xuất và quan hệ sản xuất."},{"code":"DE-ON-02","number":30,"question":"Nhân tố quan trọng hàng đầu bảo đảm thắng lợi của sự nghiệp đổi mới, hội nhập và phát triển ở nước ta là:","options":{"A":"Phát huy vai trò làm chủ của nhân dân","B":"Đảm bảo liên minh công – nông – trí thức","C":"Giữ vững và tăng cường vai trò lãnh đạo của Đảng cộng sản Việt Nam","D":"Xây dựng Nhà nước pháp quyền XHCN"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Theo cách trình bày của môn học, giữ vững và tăng cường vai trò lãnh đạo của Đảng Cộng sản Việt Nam là nhân tố quan trọng hàng đầu bảo đảm thắng lợi của đổi mới, hội nhập và phát triển."},{"code":"DE-ON-02","number":31,"question":"Căn cứ vào tính chất quyền lực, Nhà nước sẽ bao gồm những chức năng nào?","options":{"A":"Chức năng kinh tế, chính trị, văn hoá, xã hội","B":"Chức năng đối nội và đối ngoại","C":"Chức năng giai cấp và chức năng xã hội","D":"Cả A, B, C đều đúng"},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Nếu căn cứ vào tính chất của quyền lực nhà nước thì chức năng được chia thành chức năng giai cấp và chức năng xã hội; đối nội/đối ngoại là cách chia theo phạm vi, còn kinh tế/chính trị/văn hóa-xã hội là theo lĩnh vực."},{"code":"DE-ON-02","number":32,"question":"Yếu tố quyết định giai cấp nông dân không thể đảm nhận sứ mệnh lịch sử thực hiện việc chuyển biến từ xã hội TBCN lên XHCN:","options":{"A":"Họ không có hệ tư tưởng riêng độc lập","B":"Họ mang tính tư hữu cao","C":"Họ không đại diện cho phương thức sản xuất tiến bộ","D":"Họ không có chính Đảng riêng độc lập"},"key":"C","basis":"Giải và đối chiếu thêm","reason":"Giai cấp nông dân không đại diện cho phương thức sản xuất công nghiệp tiên tiến như giai cấp công nhân."},{"code":"DE-ON-02","number":33,"question":"Hình thức dân chủ quân sự xuất hiện trong xã hội nào?","options":{"A":"Tư bản chủ nghĩa","B":"Chiếm hữu nô lệ","C":"Phong kiến","D":"Công xã nguyên thuỷ"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Dân chủ quân sự là hình thức dân chủ sơ khai xuất hiện ở giai đoạn cuối của xã hội công xã nguyên thủy, trước khi nhà nước và nền dân chủ chủ nô hình thành; vì vậy D."},{"code":"DE-ON-02","number":34,"question":"Nội dung cốt lõi trong chính sách tôn giáo của Đảng và Nhà nước ta là gì?","options":{"A":"Nâng cao trách nhiệm của cả hệ thống chính trị","B":"Vấn đề theo đạo và truyền đạo","C":"Tăng cường đại đoàn kết dân tộc","D":"Công tác vận động quần chúng"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Tài liệu Chương 6 xác định nội dung cốt lõi của công tác/chính sách tôn giáo là công tác vận động quần chúng, nên D đúng."},{"code":"DE-ON-02","number":35,"question":"Biện pháp nào không đúng để phát triển kinh tế trong thời kỳ quá độ lên CNXH bỏ qua chế độ tư bản chủ nghĩa?","options":{"A":"Thực hiện nhất quán lâu dài nền kinh tế nhiều thành phần trong đó kinh tế nhà nước là chủ đạo.","B":"Phát triển nền sản xuất hàng hoá theo cơ chế thị trường.","C":"Dựa trên một hình thức phân phối là phân phối theo lao động.","D":"Thông qua chế độ hợp tác tự nguyện dẫn dắt nông dân đi lên CNXH."},"key":"C","basis":"Đối chiếu ngân hàng tài liệu","reason":"Thời kỳ quá độ tồn tại nhiều hình thức phân phối tương ứng với nhiều thành phần và hình thức sở hữu; vì vậy “chỉ dựa trên một hình thức phân phối theo lao động” là không đúng."},{"code":"DE-ON-02","number":36,"question":"Như thế nào là chế độ hôn nhân tiến bộ?","options":{"A":"Hôn nhân tự nguyện","B":"Một vợ một chồng, bình đẳng","C":"Được đảm bảo về pháp lý","D":"Cả A, B và C."},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Hôn nhân tiến bộ gồm ba yêu cầu gắn bó: tự nguyện; một vợ một chồng và vợ chồng bình đẳng; kết hôn, ly hôn được pháp luật bảo đảm. Vì A, B, C đều đúng nên chọn D."},{"code":"DE-ON-02","number":37,"question":"Ở nước ta, tổ chức nào hoạt động theo phương thức hiệp thương dân chủ, phối hợp và thống nhất hành động giữa các thành viên theo chương trình hoạt động chung:","options":{"A":"Đảng Cộng sản Việt Nam","B":"Chính phủ","C":"Quốc hội","D":"Mặt trận Tổ quốc Việt Nam"},"key":"D","basis":"Đối chiếu ngân hàng tài liệu","reason":"Mặt trận Tổ quốc Việt Nam hoạt động theo phương thức hiệp thương dân chủ, phối hợp và thống nhất hành động giữa các thành viên."},{"code":"DE-ON-02","number":38,"question":"Yếu tố nào quyết định sự liên minh giai cấp công nhân với giai cấp nông dân và tầng lớp trí thức?","options":{"A":"Do có những lợi ích cơ bản thống nhất với nhau","B":"Do giai cấp công nhân mong muốn","C":"Do mục tiêu về chính trị của giai cấp công nhân","D":"Do có cùng một kẻ thù là giai cấp tư sản"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Liên minh công nhân - nông dân - trí thức có cơ sở khách quan từ những lợi ích cơ bản thống nhất và nhu cầu gắn kết các lĩnh vực kinh tế - xã hội; không phải chỉ do mong muốn chủ quan hay cùng một kẻ thù."},{"code":"DE-ON-02","number":39,"question":"Đảng Cộng sản Việt Nam ra đời là sự kết hợp của:","options":{"A":"Chủ nghĩa Mác – Lênin, phong trào công nhân và phong trào yêu nước","B":"Chủ nghĩa Mác – Lênin, phong trào công nhân","C":"Chủ nghĩa Mác – Lênin, phong trào công nhân và tư tưởng Hồ Chí Minh","D":"Chủ nghĩa Mác – Lênin, phong trào công nhân và phong trào chống thực dân"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Ở Việt Nam, Đảng Cộng sản ra đời từ sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước; đây là nét đặc thù so với công thức chung."},{"code":"DE-ON-02","number":40,"question":"Theo quy định của giai cấp cầm quyền trong nền dân chủ chủ nô, “nhân dân” là:","options":{"A":"Chủ nô, tăng lữ, thương gia và một số trí thức","B":"Giai cấp chủ nô và nô lệ","C":"Thương gia và nô lệ","D":"Tăng lữ và một số trí thức ----------------------------------------------- ----------- HẾT ----------"},"key":"A","basis":"Đối chiếu ngân hàng tài liệu","reason":"Trong nền dân chủ chủ nô, khái niệm “nhân dân” theo quy định của giai cấp cầm quyền chỉ bao gồm những người tự do như chủ nô, tăng lữ, thương gia và một số trí thức, không bao gồm nô lệ; A phù hợp nhất."}];
